// Generated by tools/vendor-demo.sh from the site's script.js. Do not edit.
// Copy that this script writes into the page lives in <template id="i18n-js">,
// so it can be extracted and translated like any markup string. The literals
// passed here are the English fallback, used when the template is absent.
const I18N = (() => {
  const tpl = document.getElementById('i18n-js');
  const map = {};
  if (tpl) {
    for (const el of tpl.content.querySelectorAll('[data-js]')) {
      map[el.dataset.js] = el.textContent.trim();
    }
  }
  return (name, fallback) => map[name] || fallback;
})();

// Set by tools/make-video.py before any of this runs: the page is being
// recorded, and a recording is one turn of a demo's loop. Each demo announces
// the top of its loop with a `subtitles:loop` event on its own element, always,
// so the recorder knows where to cut; under this flag the demos also start
// every turn from nothing, so the turn recorded is the one a visitor sees first.
const CAPTURE = window.SUBTITLES_CAPTURE === true;

// The demos seeded with the app's settings, so the box a demo draws is the
// box the reader has. The app embeds the home demo in its windows and hands
// it the settings the overlay is running on; the keys are the app's own
// (PreviewStyle in SettingsPreview.swift), so that struct encodes straight
// into the seed. Read from window.SUBTITLES_SETTINGS, set before this script
// runs as SUBTITLES_CAPTURE is, and from the page's query string, which wins
// key by key: /demo/?fontSize=40&iconStyle=nameTab&revealEnabled=0. A key
// left out keeps the demo's own value, which each demo decides for itself
// (the landing pages start with the reveal off), so nothing is filled in
// here; a key that is not a setting, or a value that is not one, is dropped.
//
// A setting the app changes while its welcome window is up arrives later,
// as a `subtitles:settings` event on the document whose detail holds the
// keys that changed and nothing else, read the same way; the home demo
// follows those in place, see applySettings in captionDemo.
//
//   fontSize            points: the menu's 22 / 30 / 40 / 52, or any other
//   textAlignment       start | center
//   iconStyle           off | nameTab | header
//   maxLines            lines a box fills before it pages, 1 and up
//   boxOpacity          0…1, how solid the box is behind the text
//   blur                points, 0 for none
//   revealEnabled       Fade Away Under Pointer
//   revealOpacity       0…1, how much of the box the pointer takes
//   revealWidth         points, the hole's full extent; or revealSize as
//   revealHeight        {width, height} or [width, height], as CGSize encodes
//   historyEnabled      Recent Boxes On ⌥
//   historyDepth        boxes kept: 0 for none, anything past 2000 for all
//   historyTextOpacity  0…1, the stack's text against the live box's white
//   historyExpires      whether a silence forgets the stack
//   historyExpiry       seconds of silence that does
//   bothLanguages       Show Both Languages: the original under a translation
//   microphone          Listen To → the microphone, over whatever is playing
//   borealis            Audio Borealis: off | rainbow | northernLights | autumn | monochromeHaze
//   borealisStrength    strong | medium | subtle
//   theme               Color Theme, the boxes' colors: auto (the page's) | light | dark
const readSettings = (given) => {
  const NUMBER = {
    fontSize: [1, 400], maxLines: [1, 50], boxOpacity: [0, 1], blur: [0, 200],
    revealOpacity: [0, 1], revealWidth: [1, 1e5], revealHeight: [1, 1e5],
    historyDepth: [0, Infinity], historyTextOpacity: [0, 1], historyExpiry: [0, 1e7],
  };
  const WHOLE = ['maxLines', 'historyDepth'];
  const FLAG = ['revealEnabled', 'historyEnabled', 'historyExpires', 'bothLanguages', 'microphone'];
  const WORD = {
    textAlignment: ['start', 'center'], iconStyle: ['off', 'nameTab', 'header'],
    borealis: ['off', 'rainbow', 'northernLights', 'autumn', 'monochromeHaze'],
    borealisStrength: ['strong', 'medium', 'subtle'],
    theme: ['auto', 'light', 'dark'],
  };
  const out = {};
  const take = (key, value) => {
    if (key === 'revealSize') {
      if (!value || typeof value !== 'object') return;
      take('revealWidth', Array.isArray(value) ? value[0] : value.width);
      take('revealHeight', Array.isArray(value) ? value[1] : value.height);
    } else if (key in NUMBER) {
      let n = typeof value === 'string' ? parseFloat(value) : Number(value);
      if (Number.isNaN(n) || n < NUMBER[key][0] || n > NUMBER[key][1]) return;
      if (WHOLE.includes(key) && Number.isFinite(n)) n = Math.round(n);
      out[key] = n;
    } else if (FLAG.includes(key)) {
      out[key] = typeof value === 'string' ? !/^(0|false|off|no)$/i.test(value.trim()) : !!value;
    } else if (key in WORD) {
      if (WORD[key].includes(value)) out[key] = value;
    }
  };
  if (given && typeof given === 'object') Object.keys(given).forEach((k) => take(k, given[k]));
  return out;
};
const SETTINGS = (() => {
  const out = readSettings(window.SUBTITLES_SETTINGS);
  try {
    Object.assign(out, readSettings(Object.fromEntries(new URLSearchParams(location.search))));
  } catch (e) { /* no location */ }
  return out;
})();

(function waveFit() {
  const wave = document.getElementById('pod-wave');
  if (!wave || !('ResizeObserver' in window)) return;
  const bars = [...wave.children];
  const n = bars.length;
  if (n < 2) return;
  const fit = () => {
    const dpr = window.devicePixelRatio || 1;
    const width = Math.floor(wave.clientWidth * dpr);
    if (width < n * 2) return;
    // Bars four times the gap, as the stylesheet draws them.
    const unit = width / (n * 4 + (n - 1));
    const gap = Math.max(1, Math.round(unit));
    const bar = Math.max(1, Math.floor((width - (n - 1) * gap) / n));
    const spare = width - n * bar - (n - 1) * gap;
    wave.style.gap = '0px';
    bars.forEach((b, i) => {
      b.style.width = bar / dpr + 'px';
      b.style.marginInlineEnd = i < n - 1 ? (gap + (i < spare ? 1 : 0)) / dpr + 'px' : '0px';
    });
  };
  new ResizeObserver(fit).observe(wave);
  window.addEventListener('resize', fit);
  fit();
})();

// ── searching the ⌥ stack ────────────────────────────────────────────────────
// The app's HistorySearchView, shared by both demos. A field sits at the
// stack's edge touching the live box, drawn as one more box. Click it, or
// press ⌥F while the stack is up, and the stack is pinned for as long as the
// field has the keyboard: it stays up with ⌥ released, so both hands are free
// to type. Typing narrows the stack to the boxes containing the text, with the
// matches lit; clearing the field shows every box again and keeps the pin.
// Escape or a click anywhere outside the stack unpins it, and the stack goes
// back to living under ⌥. The numbers are the app's, at 30pt of text, so in
// em of the boxes.
// The stack's fade at its edges is drawn on each box rather than on the stack:
// a mask on the stack would make it the backdrop root for everything in it,
// and a box's backdrop-filter would then have only the stack's own transparent
// pixels to blur. So each box carries its own mask, positioned from where the
// box sits in the stack's view (--y) against the stack's height (--h) and the
// two bands (--fade, --near-fade) the demos measure; styles.css does the rest.
// Reads first, then writes, so a stack of fifteen costs one layout.
const placeFade = (history) => {
  const top = history.scrollTop;
  const lines = [...history.children];
  const ys = lines.map((line) => line.offsetTop - top);
  history.style.setProperty('--h', history.clientHeight + 'px');
  lines.forEach((line, i) => line.style.setProperty('--y', ys[i].toFixed(1) + 'px'));
  if (nameTab) nameTab.refresh(history);
};

// The source app's row on a box, see .ov-app in styles.css: the icon of the
// app whose audio the box holds and its name, as the app's header row draws
// them since 1.7.0. `app` is {icon, name}, the icon a file in assets/apps/dock/
// (the switcher's, as the Dock draws it), or null for a box with no known
// source, when the row goes and the box is text alone, as the app's is.
const wearApp = (box, app) => {
  const row = box.querySelector('.ov-app');
  if (!row) return;
  box.dataset.named = app ? '1' : '0';
  if (app) {
    const img = row.querySelector('img');
    const src = 'assets/apps/dock/' + app.icon + '.png';
    if (img && img.getAttribute('src') !== src) img.setAttribute('src', src);
    const name = row.querySelector('.ov-name');
    if (name && name.textContent !== app.name) name.textContent = app.name;
  }
  dressBox(box, !!app);
};

// The microphone as a box's source, from Listen To: the app's own stand-in
// for a source that is not an app — a white mic on a system-red tile, drawn
// by AppCatalog.microphoneIcon and rendered to assets/apps/dock/ — under the
// label AudioSource.microphone carries. A box wears it like any app's row.
const MIC = { icon: 'microphone', name: 'Microphone' };

// A box for the ⌥ stack, wearing `app`: the row, and under it the text,
// which is what the search writes into.
const newBox = (app) => {
  const el = document.createElement('div');
  el.className = 'hist-line';
  const row = document.createElement('span');
  row.className = 'ov-app';
  const img = document.createElement('img');
  img.alt = '';
  const name = document.createElement('span');
  name.className = 'ov-name';
  row.append(img, name);
  const text = document.createElement('span');
  text.className = 'ov-text';
  const under = document.createElement('span');
  under.className = 'ov-under';
  el.append(row, text, under);
  wearApp(el, app);
  return el;
};
const textOf = (el) => el.querySelector('.ov-text') || el;
// The other language under a box's text, with Show Both Languages on: the
// app's SubtitleView.secondary, a second paragraph in a smaller, dimmer run
// (.ov-under in styles.css), empty and taking no room when a box has only
// the one language. The live boxes' markup has no span for it, so the first
// write makes one; the stack's boxes are built with theirs above.
const underOf = (el) => {
  let under = el.querySelector('.ov-under');
  if (!under) {
    under = document.createElement('span');
    under.className = 'ov-under';
    el.append(under);
  }
  return under;
};
const setUnder = (el, text) => {
  const under = underOf(el);
  if (!text) { if (under.firstChild) under.textContent = ''; return; }
  setKeys(under, text);
};

// A keyboard shortcut said inside a demo is drawn as a keycap: a run of
// modifier glyphs, with the key letter it may carry (⌥F), becomes a <kbd>,
// and whatever the sentence glues to it stays text: the comma in "pulsa ⌥,",
// the particle in "⌥를", the "-Stapel" in German, the sentence a Japanese
// line runs straight into. Drawn from the text as the engines type it and as
// the stack's boxes are written, and once over the scene labels, so no
// translated string carries markup for it.
const KEYCAP = /[⌥⇧⌃⌘]+[A-Z0-9]?/g;
const appendKeys = (el, text) => {
  let at = 0;
  for (const m of text.matchAll(KEYCAP)) {
    if (m.index > at) el.append(text.slice(at, m.index));
    const key = document.createElement('kbd');
    key.textContent = m[0];
    el.append(key);
    at = m.index + m[0].length;
  }
  if (at < text.length) el.append(text.slice(at));
};
const setKeys = (el, text) => { el.textContent = ''; appendKeys(el, text); };
(function keycapLabels() {
  document.querySelectorAll('.scene-label').forEach((el) => {
    if (!el.querySelector('kbd') && /[⌥⇧⌃⌘]/.test(el.textContent)) setKeys(el, el.textContent);
  });
})();

// A box's layer rebuilt once its entrance has played. Chrome on the GPU
// paints a box that has just run a transform animation a fraction of a pixel
// down from where it sits, on its top and bottom edges only, for as long as
// that layer lives: the hairline there sits across two rows. Nothing about
// where the box is changes it, and neither does repainting it; the layer
// has to go. Without will-change for a frame it does, and comes back whole.
// Blink only: Safari and Firefox draw the box whole where it lands.
const relayer = (el) => {
  if (!navigator.userAgentData) return;
  el.style.willChange = 'auto';
  requestAnimationFrame(() => requestAnimationFrame(() => { el.style.willChange = ''; }));
};

// The ⇧ ring on a live box, see .ov-ring in styles.css: one rounded rect
// stroked twice, white dashes and black dashes a dash apart, so one tone or
// the other shows against whatever the box sits over. Built here rather than
// in the markup, since only script can hold ⇧.
const ringFor = (box) => {
  if (!box) return;
  // The tab's ring as well, a sibling outside the mask, whenever the box
  // wears the tab; the ring below stays, hidden by the stylesheet meanwhile,
  // for when the box goes back to the header row.
  if (nameTab && nameTab.on) nameTab.ring(box);
  if (box.querySelector('.ov-ring')) return;
  const NS = 'http://www.w3.org/2000/svg';
  const svg = document.createElementNS(NS, 'svg');
  svg.setAttribute('class', 'ov-ring');
  svg.setAttribute('aria-hidden', 'true');
  ['ring-white', 'ring-black'].forEach((tone) => {
    const rect = document.createElementNS(NS, 'rect');
    rect.setAttribute('class', tone);
    svg.append(rect);
  });
  box.append(svg);
};

// ── AudioBorealis ───────────────────────────────────────────────────────────
// The glow the sound raises along the bottom of the box, as the app draws
// it (app/captions/AudioBorealis.swift is the driver this is a line-for-line
// port of, app/macos/AudioBorealisPainter.swift the painter): seven soft
// lobes fanned out from the bottom edge, each on a band of the voice,
// sliding sideways while a voice is heard, and over them one translucent
// hill per band, filled with a colour of the hue wheel, rising as its band
// is heard. Silence is nothing. The site has no sound to read, so a mock
// voice drives it: syllables while words land in the box, quiet between.
// Every number is the app's; the menu's Audio Borealis rows pick a look
// (where on the hue wheel the colours sit, or white alone) and a strength
// (the whole effect's opacity), and a page can seed both (see SETTINGS).
//
// Painted on a canvas laid inside the box under its text, in plain 2D
// calls every engine has (gradients, clips, destination-in for the masks,
// lighter for an additive blend): no filters, no OffscreenCanvas, no
// roundRect, so Chrome, Safari and Firefox draw the same picture.
const borealis = (() => {
  const TAU = Math.PI * 2;
  const clamp01 = (v) => (v < 0 ? 0 : v > 1 ? 1 : v);
  const wrap = (v, span) => { const m = v % span; return m < 0 ? m + span : m; };
  const wrapX = (x, span) => wrap(x + span / 2, span) - span / 2;
  const edgeEnvelope = (x, span) => { const t = x / (span / 2 + 4); return Math.max(0, 1 - t * t); };
  const pingPong = (phase) => (1 - Math.cos(TAU * phase)) / 2;
  // Noise gate then soft saturation, so a shout rounds off instead of clipping.
  const shape = (raw, threshold) => {
    if (raw <= threshold) return 0;
    const t = (raw - threshold) / Math.max(0.001, 1 - threshold);
    return clamp01((1 - Math.exp(-3 * t)) / (1 - Math.exp(-3)));
  };
  // One-pole follower: fast up (attack), slow down (release).
  const follow = (prev, target, dt, attack, release) => {
    const tau = target > prev ? attack : release;
    return prev + (target - prev) * (1 - Math.exp(-dt / Math.max(0.001, tau)));
  };
  // A hill, 1 at the centre and exactly 0 at the ends.
  const bell = (t, p, sigma, skew) => {
    const side = t < 0 ? 1 - skew : 1 + skew;
    const s = Math.max(0.05, sigma * side);
    const v = Math.exp(-Math.pow(Math.abs(t) / s, p));
    const tail = Math.exp(-Math.pow(1 / s, p));
    return Math.max(0, (v - tail) / (1 - tail));
  };
  const hsb = (h, s, v) => {
    const sector = h * 6;
    const i = Math.floor(sector) % 6;
    const f = sector - Math.floor(sector);
    const p = v * (1 - s), q = v * (1 - s * f), t = v * (1 - s * (1 - f));
    return [[v, t, p], [q, v, p], [p, v, t], [p, q, v], [t, p, v], [v, p, q]][i];
  };

  // The knobs, the app's defaults.
  const defaults = () => ({
    sensitivity: 3, threshold: 0.06, curve: 0.6,
    autoGain: true, autoGainFloor: 0.3, autoGainRelease: 4,
    attack: 0.05, release: 0.2, idle: 0, breatheDuration: 5.2,
    reach: 1.7, spread: 1.05, flow: 60, lobeSpacing: 0.85,
    hueRange: 24, hueDuration: 12,
    hueStart: 0, hueWidth: 360, saturation: 0.85, colorMode: 'spectrum',
    opacity: 0.5, glowOpacity: 1, bend: 60,
    curveCount: 5, curveOpacity: 0.2, curveEdge: 0.35, curveFade: 0.35, curveBlend: 'normal',
    curvePosition: 0.25, curveCeiling: 0.55, curveBase: 0, curveOffset: -1.5,
    curveShape: 1.75, curveSpread: 0.87, curveSpan: 0.5,
    curveWidthCentre: 0.55, curveWidthEdge: 0.32, curveWander: 0.084,
  });
  // The bands of the voice, low to high: the upper edge of each in Hz, the
  // last open. Five, as the app's meter splits them.
  const BAND_COUNT = 5;
  // Seven lobes: the centre on the lows, its neighbours on the mids, the
  // outer pair on the highs and the far pair on the low mids.
  const LOBES = [
    { x: 0, w: 74, h: 46, band: 0 },
    { x: -36, w: 54, h: 40, band: 2 }, { x: 36, w: 54, h: 40, band: 2 },
    { x: -72, w: 48, h: 32, band: 4 }, { x: 72, w: 48, h: 32, band: 4 },
    { x: -108, w: 42, h: 26, band: 1 }, { x: 108, w: 42, h: 26, band: 1 },
  ];
  const LOBE_SPAN = 36 * LOBES.length;
  const CEILING_HALF_WIDTH = 170, CEILING_HEIGHT = 64, RANGE_WIDTH = 0.75;
  // Where on the hue wheel each of the seven colours sits, shuffled so
  // neighbours contrast. The curves take the first ones, low band to high.
  const HUE_SHARES = [0.94, 0.56, 0.76, 0.40, 0.08, 0.65, 0.49];
  const BASE_GAIN = 5;
  // The menu's looks and strengths.
  const LOOKS = {
    rainbow: { colorMode: 'spectrum', hueStart: 0, hueWidth: 360 },
    northernLights: { colorMode: 'spectrum', hueStart: 100, hueWidth: 180 },
    autumn: { colorMode: 'spectrum', hueStart: 310, hueWidth: 90 },
    // The opposite of the box's color: white on the dark box, a dark grey
    // on the light one, read off the box where it is painted (`inkOf`).
    monochromeHaze: { colorMode: 'monochrome' },
  };
  const STRENGTHS = { strong: 1, medium: 0.5, subtle: 0.35 };

  // The `index`th colour: its share of the wheel from the start, turned by
  // the drift, at the saturation; or white or black alone; or, monochrome,
  // `ink`, the box's counter-colour, white unless the box says otherwise.
  const color = (index, c, drift, ink) => {
    if (c.colorMode === 'white') return [1, 1, 1];
    if (c.colorMode === 'black') return [0, 0, 0];
    if (c.colorMode === 'monochrome') return ink || [1, 1, 1];
    const hue = wrap(c.hueStart + c.hueWidth * HUE_SHARES[index % HUE_SHARES.length] + drift, 360);
    return hsb(hue / 360, clamp01(c.saturation), 1);
  };
  const rgba = (rgb, a) => `rgba(${Math.round(rgb[0] * 255)}, ${Math.round(rgb[1] * 255)}, ${Math.round(rgb[2] * 255)}, ${a.toFixed(3)})`;
  // Of `count` curves, where the `index`th rests: the centre-most first,
  // the rest alternating outward, the outermost at `span`.
  const curveOffset = (index, count, span) => {
    if (count < 2) return 0;
    const slots = [];
    for (let i = 0; i < count; i++) slots.push(-span + (2 * span * i) / (count - 1));
    slots.sort((a, b) => (Math.abs(a) - Math.abs(b)) || (a - b));
    return slots[Math.min(index, count - 1)];
  };
  const curveBand = (index, count) => (count < 2 ? 0 : Math.round((index * (BAND_COUNT - 1)) / (count - 1)));

  // The driver: a loudness in, a frame out.
  const driver = (config) => {
    const s = {
      config: config || defaults(),
      level: 0, bands: new Array(BAND_COUNT).fill(0), levelPeak: 0, bandPeak: 0, phase: 0, time: 0,
    };
    const reset = () => {
      s.level = 0; s.bands.fill(0); s.levelPeak = 0; s.bandPeak = 0; s.phase = 0; s.time = 0;
    };
    const step = (dt, loudness, input) => {
      s.time += dt;
      const c = s.config;
      const n = BAND_COUNT;
      const rawLevel = loudness * BASE_GAIN * c.sensitivity;
      const rawBands = new Array(n);
      if (input && input.length === n) {
        for (let b = 0; b < n; b++) rawBands[b] = input[b];
      } else {
        const raw = clamp01(rawLevel);
        for (let b = 0; b < n; b++) {
          const wobble = Math.sin(s.time * (7.3 + 3.1 * b) + b * 1.9);
          rawBands[b] = raw * (0.55 + 0.45 * wobble) * (1 - 0.12 * b);
        }
      }
      let target = shape(rawLevel, c.threshold);
      const targets = new Array(n);
      const gate = c.threshold * 0.6;
      for (let b = 0; b < n; b++) targets[b] = clamp01((rawBands[b] - gate) / Math.max(0.001, 1 - gate));
      if (c.autoGain) {
        const decay = Math.exp(-dt / Math.max(0.05, c.autoGainRelease));
        const floor = Math.max(0.01, Math.min(1, c.autoGainFloor));
        s.levelPeak = Math.max(target, s.levelPeak * decay, floor);
        target = Math.min(1, target / s.levelPeak);
        s.bandPeak = Math.max(Math.max(...targets), s.bandPeak * decay, floor);
        for (let b = 0; b < n; b++) targets[b] = Math.min(1, targets[b] / s.bandPeak);
      }
      s.level = follow(s.level, target, dt, c.attack, c.release);
      for (let b = 0; b < n; b++) s.bands[b] = follow(s.bands[b], targets[b], dt, c.attack, c.release * 1.15);
      const breathe = 0.5 + 0.5 * Math.sin((TAU * s.time) / c.breatheDuration);
      const eff = s.level + (1 - s.level) * c.idle * breathe;
      const rise = Math.pow(clamp01(eff), Math.max(0.1, c.curve));
      const span = LOBE_SPAN * c.lobeSpacing;
      if (c.flow !== 0) s.phase = wrap(s.phase + c.flow * rise * dt, span);
      const lobeX = [], lobeAmplitude = [];
      LOBES.forEach((lobe) => {
        const x = wrapX(lobe.x * c.lobeSpacing + s.phase, span);
        lobeX.push(x);
        lobeAmplitude.push((0.6 + 0.7 * s.bands[Math.min(lobe.band, n - 1)]) * edgeEnvelope(x, span));
      });
      const hue = c.hueRange === 0 ? 0 : -c.hueRange + 2 * c.hueRange * pingPong(s.time / c.hueDuration);
      const lift = Math.max(0, c.bend * rise);
      return {
        config: c, level: s.level, bands: s.bands.slice(), glow: rise, height: c.reach * rise,
        width: 0.85 + c.spread * rise, hue: hue, lift: lift, bend: c.bend > 0 ? Math.min(1, lift / c.bend) : 0,
        flow: s.phase / Math.max(1, span), lobeX: lobeX, lobeAmplitude: lobeAmplitude,
      };
    };
    return { state: s, step: step, reset: reset };
  };

  // The curves of a frame, one per band: points as [x, y], x from the
  // box's left edge and y the height above its bottom edge, in the box's px.
  const curves = (frame, width, height, scaleX, scaleY, samples) => {
    const c = frame.config;
    const ceiling = Math.min(height * c.curveCeiling, (CEILING_HEIGHT * frame.height + frame.lift) * c.curvePosition * scaleY);
    const base = (c.curveOffset + c.curveBase * frame.bend) * scaleY;
    const steps = Math.max(1, samples || 40);
    const count = Math.max(1, c.curveCount);
    const out = [];
    for (let k = 0; k < count; k++) {
      const b = Math.min(curveBand(k, count), frame.bands.length - 1);
      const apex = ceiling * (0.15 + 0.85 * (b >= 0 ? frame.bands[b] : 0));
      const offset = curveOffset(k, count, c.curveSpan);
      const wander = c.curveWander * Math.sin(TAU * frame.flow + k * 1.7);
      const centre = width * (0.5 + offset + wander);
      const share = c.curveSpan > 0 ? Math.min(1, Math.abs(offset) / c.curveSpan) : 0;
      const half = Math.max(1, width * (c.curveWidthCentre + (c.curveWidthEdge - c.curveWidthCentre) * share));
      const points = [];
      for (let i = 0; i <= steps; i++) {
        const x = (width * i) / steps;
        const t = Math.max(-1, Math.min(1, (x - centre) / half));
        points.push([x, base + apex * bell(t, c.curveShape, c.curveSpread, 0)]);
      }
      out.push(points);
    }
    return out;
  };

  // The painter: a frame onto a box's canvas.
  const LAYERS = [
    { sizeX: 1.15 * 1.15, sizeY: 1.5 * 1.15, opacity: 0.5,
      stops: [[0, 0.5], [0.4, 0.22], [0.75, 0.05], [1, 0]],
      mask: [200 * RANGE_WIDTH, 130], maskStops: [[0, 1], [0.35, 0.5], [0.8, 0.1], [1, 0]] },
    { sizeX: 1, sizeY: 1.1, opacity: 0.6,
      stops: [[0, 0.6], [0.45, 0.3], [0.8, 0.06], [1, 0]],
      mask: [CEILING_HALF_WIDTH * RANGE_WIDTH, CEILING_HEIGHT], maskStops: [[0, 1], [0.45, 0.5], [0.85, 0.2], [1, 0]] },
  ];
  const GLOW_WIDTH = 0.65, GLOW_HEIGHT = 1.25;
  // The vertical scale over the app's: the demo's box is set at a smaller
  // size inside a screen scaled down to fit, where the app's glow, at the
  // same share of the type, reads taller against its text. This much has
  // the peaks clear the top of the last line as they do in the app.
  const PEAK_LIFT = 1.2;
  // A radial gradient of one colour squashed into an ellipse, its alpha
  // over the radius given by the stops; `beyond` paints the last stop past
  // the radius too (a clip does that here).
  const ellipse = (ctx, cx, cy, rx, ry, rgb, stops, beyond) => {
    if (rx <= 0 || ry <= 0) return;
    ctx.save();
    ctx.translate(cx, cy);
    ctx.scale(1, ry / rx);
    const g = ctx.createRadialGradient(0, 0, 0, 0, 0, rx);
    stops.forEach(([at, a]) => g.addColorStop(at, rgba(rgb, a)));
    ctx.fillStyle = g;
    if (beyond) {
      ctx.fillRect(-1e4, -1e4, 2e4, 2e4);
    } else {
      ctx.beginPath();
      ctx.arc(0, 0, rx, 0, TAU);
      ctx.fill();
    }
    ctx.restore();
  };
  const roundedRect = (ctx, x, y, w, h, r) => {
    const rad = Math.max(0, Math.min(r, w / 2, h / 2));
    ctx.beginPath();
    ctx.moveTo(x + rad, y);
    ctx.lineTo(x + w - rad, y);
    ctx.arc(x + w - rad, y + rad, rad, -Math.PI / 2, 0);
    ctx.lineTo(x + w, y + h - rad);
    ctx.arc(x + w - rad, y + h - rad, rad, 0, Math.PI / 2);
    ctx.lineTo(x + rad, y + h);
    ctx.arc(x + rad, y + h - rad, rad, Math.PI / 2, Math.PI);
    ctx.lineTo(x, y + rad);
    ctx.arc(x + rad, y + rad, rad, Math.PI, Math.PI * 1.5);
    ctx.closePath();
  };
  // Paint `frame` on `ctx`, a box `w` by `h` CSS px with corners of `radius`
  // and type of `fontPx`, `scratch` a second canvas the masked layers are
  // built on. Canvas y runs down: the bottom edge is y = h.
  const paint = (ctx, scratch, frame, w, h, radius, fontPx, ink) => {
    const c = frame.config;
    const opacity = clamp01(c.opacity);
    ctx.clearRect(0, 0, w, h);
    if (frame.glow <= 0.002 || opacity <= 0) return;
    const sx = Math.min(2.4, Math.max(0.9, w / 350));
    const sy = Math.max(0.5, fontPx / 30) * PEAK_LIFT;
    const cx = w / 2, cy = h;
    ctx.save();
    roundedRect(ctx, 0, 0, w, h, radius);
    ctx.clip();
    // The two soft layers of lobes, each built on the scratch canvas,
    // masked to its ellipse there, and laid on at its opacity.
    if (c.glowOpacity > 0) {
      const sc = scratch.getContext('2d');
      LAYERS.forEach((layer) => {
        const alpha = Math.min(1, layer.opacity * frame.glow * c.glowOpacity);
        const rx = layer.mask[0] * frame.width * sx;
        const ry = (layer.mask[1] * frame.height + frame.lift) * sy;
        if (alpha <= 0 || rx <= 0.5 || ry <= 0.5) return;
        sc.setTransform(ctx.getTransform());
        sc.clearRect(0, 0, w, h);
        sc.save();
        sc.beginPath();
        sc.rect(cx - rx, cy - ry, rx * 2, ry * 2);
        sc.clip();
        sc.globalCompositeOperation = 'source-over';
        LOBES.forEach((lobe, i) => {
          const lrx = lobe.w * GLOW_WIDTH * layer.sizeX * frame.width * sx;
          const lry = lobe.h * GLOW_HEIGHT * layer.sizeY * frame.height * frame.lobeAmplitude[i] * sy;
          if (lrx <= 0.5 || lry <= 0.5) return;
          ellipse(sc, cx + frame.lobeX[i] * frame.width * sx, cy, lrx, lry, color(i, c, frame.hue, ink), layer.stops, false);
        });
        sc.globalCompositeOperation = 'destination-in';
        ellipse(sc, cx, cy, rx, ry, [1, 1, 1], layer.maskStops, true);
        sc.restore();
        // Laid on at identity, pixel for pixel, the box's transform put back.
        const t = ctx.getTransform();
        ctx.globalAlpha = alpha * opacity;
        ctx.setTransform(1, 0, 0, 1, 0, 0);
        ctx.drawImage(scratch, 0, 0);
        ctx.setTransform(t);
        ctx.globalAlpha = 1;
        sc.setTransform(1, 0, 0, 1, 0, 0);
      });
    }
    // The curves: a hill per band, filled from the bottom edge up to its
    // curve, the fill anchored at the edge and fading toward the crest,
    // and a line along the hill above the band it stands on.
    const fill = c.curveOpacity * opacity;
    const edge = c.curveEdge * opacity;
    if (fill > 0.003 || edge > 0.003) {
      const hills = curves(frame, w, h, sx, sy, 40);
      const band = (c.curveOffset + c.curveBase * frame.bend) * sy;
      hills.forEach((points, k) => {
        if (!points.some((p) => p[1] > 0.3)) return;
        const rgb = color(k, c, frame.hue, ink);
        const crest = Math.max(...points.map((p) => p[1]));
        ctx.save();
        ctx.beginPath();
        ctx.moveTo(points[0][0], h + 4);
        points.forEach((p) => ctx.lineTo(p[0], h - p[1]));
        ctx.lineTo(points[points.length - 1][0], h + 4);
        ctx.closePath();
        ctx.clip();
        ctx.globalCompositeOperation = c.curveBlend === 'additive' ? 'lighter' : 'source-over';
        if (fill > 0.003) {
          const g = ctx.createLinearGradient(0, h, 0, h - Math.max(crest, 1));
          g.addColorStop(0, rgba(rgb, fill));
          g.addColorStop(1, rgba(rgb, fill * clamp01(c.curveFade)));
          ctx.fillStyle = g;
          ctx.fillRect(0, 0, w, h + 4);
        }
        ctx.restore();
        if (edge > 0.003 && crest > band + 1.5) {
          ctx.save();
          ctx.beginPath();
          ctx.rect(0, 0, w, h - band - 1.5);
          ctx.clip();
          ctx.beginPath();
          points.forEach((p, i) => (i ? ctx.lineTo(p[0], h - p[1]) : ctx.moveTo(p[0], h - p[1])));
          ctx.strokeStyle = rgba(rgb, edge);
          ctx.lineWidth = 1;
          ctx.lineJoin = 'round';
          ctx.stroke();
          ctx.restore();
        }
      });
    }
    ctx.restore();
  };
  // A voice that is not there, close enough to one that the meter would
  // read the same: syllables of uneven length and loudness, some stressed,
  // laid end to end with a short gap now and then where a word ends, each
  // with a spectral shape of its own (a vowel sits low and in the mids, a
  // consonant higher) and a third of them opening on a burst of highs, a
  // sibilant. Deterministic in time, from a hash, so the loop repeats and
  // nothing is stored: eight syllables fill a cycle of fixed length, and the
  // cycle's index reseeds them. `speaking` gates it: quiet otherwise.
  const CYCLE = 1.7;
  const PER_CYCLE = 8;
  /// How loud the mock voice is, on the syllables as authored.
  const MOCK_GAIN = 1.2;
  const hash = (n, k) => { const x = Math.sin(n * 127.1 + k * 311.7) * 43758.5453; return x - Math.floor(x); };
  const mockVoice = (t, speaking) => {
    const bands = new Array(BAND_COUNT).fill(0);
    if (!speaking) return { loudness: 0.0015, bands: bands };
    const cycle = Math.floor(t / CYCLE);
    let local = t - cycle * CYCLE;
    // The cycle's syllables, their lengths scaled to fill it exactly.
    const spans = [];
    let total = 0;
    for (let i = 0; i < PER_CYCLE; i++) {
      const n = cycle * PER_CYCLE + i;
      const dur = 0.14 + 0.16 * hash(n, 2);
      const gap = hash(n, 3) < 0.18 ? 0.04 + 0.07 * hash(n, 4) : 0.01;
      spans.push([dur, gap]);
      total += dur + gap;
    }
    const scale = CYCLE / total;
    let loudness = 0.0015;
    for (let i = 0; i < PER_CYCLE; i++) {
      const n = cycle * PER_CYCLE + i;
      const dur = spans[i][0] * scale, gap = spans[i][1] * scale;
      if (local < dur) {
        // Inside this syllable: a rounded rise, a slight sag, a rounded
        // fall, as a voice swells rather than switches; loud on the whole,
        // as a voice the meter reads is once the automatic gain has scaled
        // it to its own peaks. Where it sits in the spectrum crosses over
        // from the syllable before, so the bands glide rather than jump.
        const ease = (u) => 0.5 - 0.5 * Math.cos(Math.PI * Math.min(1, Math.max(0, u)));
        const amp = n === 0 ? 1 : 0.7 + 0.3 * Math.pow(hash(n, 1), 0.7);
        const env = Math.min(ease(local / 0.07), ease((dur - local) / 0.09)) * (1 - 0.1 * (local / dur));
        const focusOf = (m) => 0.4 + 2.6 * Math.pow(hash(m, 5), 1.4);
        const focus = focusOf(n - 1) + (focusOf(n) - focusOf(n - 1)) * ease(local / (dur * 0.6));
        const burst = hash(n, 6) < 0.35 ? ease(1 - local / 0.09) * 0.7 : 0;
        for (let b = 0; b < BAND_COUNT; b++) {
          const d = b - focus;
          const shape = Math.exp(-(d * d) / 2);
          bands[b] = Math.min(1, amp * env * (0.15 + 0.85 * shape) + (b >= 3 ? burst : 0));
        }
        loudness = 0.0015 + (0.06 * amp * env + 0.015 * burst) * MOCK_GAIN;
        break;
      }
      local -= dur + gap;
    }
    return { loudness: loudness, bands: bands };
  };

  // One shared frame loop for every box on the page, running only while a
  // box has something to show.
  const boxes = new Set();
  let raf = 0;
  let last = 0;
  const frameAll = (ts) => {
    raf = 0;
    const dt = last ? Math.min(0.05, (ts - last) / 1000) : 1 / 60;
    last = ts;
    let busy = false;
    boxes.forEach((b) => { if (b.tick(dt, ts)) busy = true; });
    if (busy && !document.hidden) raf = requestAnimationFrame(frameAll);
    else last = 0;
  };
  const wake = () => { if (!raf && !document.hidden) raf = requestAnimationFrame(frameAll); };
  document.addEventListener('visibilitychange', () => { if (!document.hidden) wake(); });

  // The glow on one box: a canvas under its text, sized with it, stepped on
  // the mock voice while words land in it. `apply(S)` reads the demo's
  // settings, its look and strength; `speak()` marks a word landing.
  const attach = (box) => {
    if (!box) return null;
    const canvas = document.createElement('canvas');
    canvas.className = 'ov-borealis';
    canvas.setAttribute('aria-hidden', 'true');
    box.prepend(canvas);
    const scratch = document.createElement('canvas');
    const drive = driver(defaults());
    let enabled = true;
    let spokeAt = -1e9;
    // When the caption being spoken began: the mock voice starts over
    // there, so every caption is said the same way, to the same peak.
    let captionStart = 0;
    let wasSpeaking = false;
    let w = 0, h = 0, dpr = 1, radius = 16, fontPx = 20;
    let wasBlank = true;
    let lastFrame = null;
    // The box's own size, not its size on the page: the demo's screen is
    // scaled to fit, and the canvas is laid out in the box's own px.
    const size = () => {
      const cs = getComputedStyle(box);
      w = Math.max(1, Math.round(box.offsetWidth));
      h = Math.max(1, Math.round(box.offsetHeight));
      dpr = Math.min(3, window.devicePixelRatio || 1);
      radius = parseFloat(cs.borderTopLeftRadius) || 0;
      fontPx = parseFloat(cs.fontSize) || 20;
      [canvas, scratch].forEach((el) => {
        el.width = Math.round(w * dpr);
        el.height = Math.round(h * dpr);
      });
    };
    // The monochrome haze's colour: the opposite of the box's, which is
    // read off the box's own type, white on a dark box and on a light one a
    // 65% grey leaning blue (#475975), as the app's painter has it (black
    // read as a stain, neutral grey as concrete), so it follows the theme
    // wherever the theme comes from, the page's or the menu's. Read only
    // when the look asks for it.
    const inkOf = () => {
      if (drive.state.config.colorMode !== 'monochrome') return null;
      const rgb = (getComputedStyle(box).color.match(/[\d.]+/g) || [255, 255, 255]).map(Number);
      return rgb[0] * 0.299 + rgb[1] * 0.587 + rgb[2] * 0.114 > 128 ? [1, 1, 1] : [0.28, 0.35, 0.46];
    };
    const draw = (frame) => {
      const ctx = canvas.getContext('2d');
      ctx.setTransform(dpr, 0, 0, dpr, 0, 0);
      paint(ctx, scratch, frame, w, h, radius, fontPx, inkOf());
    };
    size();
    // Sizing a canvas clears it, and the box resizes on almost every word:
    // painted again at once, in the resize callback (after layout, before
    // the frame is painted), so the glow never blinks out for a frame.
    if (typeof ResizeObserver === 'function') {
      new ResizeObserver(() => { size(); if (lastFrame && !wasBlank) draw(lastFrame); wake(); }).observe(box);
    }
    // A word landing: the box's text changed.
    const speak = () => { spokeAt = performance.now(); wake(); };
    if (typeof MutationObserver === 'function') {
      new MutationObserver(speak).observe(box, { childList: true, characterData: true, subtree: true });
    }
    const tick = (dt, ts) => {
      // A word landed within the last half second: the voice is still going.
      const speaking = enabled && box.classList.contains('is-visible') && ts - spokeAt < 450;
      if (speaking && !wasSpeaking) captionStart = ts;
      wasSpeaking = speaking;
      const mock = mockVoice((ts - captionStart) / 1000, speaking);
      const frame = drive.step(dt, enabled ? mock.loudness : 0, enabled ? mock.bands : null);
      lastFrame = frame;
      const blank = frame.glow <= 0.002;
      if (blank && wasBlank) return false;
      wasBlank = blank;
      draw(frame);
      return !blank;
    };
    const entry = {
      tick: tick,
      debug: () => ({ w: w, h: h, dpr: dpr, radius: radius, fontPx: fontPx, enabled: enabled,
        sinceWord: performance.now() - spokeAt, glow: lastFrame ? lastFrame.glow : null, blank: wasBlank,
        frame: lastFrame }),
    };
    boxes.add(entry);
    return {
      apply: (S) => {
        const c = drive.state.config;
        enabled = S.borealis !== 'off';
        const look = LOOKS[S.borealis] || LOOKS.rainbow;
        Object.assign(c, { colorMode: 'spectrum' }, look);
        c.opacity = STRENGTHS[S.borealisStrength] || STRENGTHS.medium;
        if (!enabled) drive.reset();
        wake();
      },
      speak: speak,
    };
  };

  return {
    attach: attach, defaults: defaults, LOOKS: LOOKS, STRENGTHS: STRENGTHS, mockVoice: mockVoice,
    /** Each box's state, for a console. */
    debug: () => [...boxes].map((b) => b.debug()),
  };
})();

// Show Source App Name → Name Tab, from the menu: the row sits on the pill's
// top edge as a tab, flush with the leading side, as Pill.tabPath draws it,
// and the box is masked to the silhouette of pill and tab. The mask is on the
// box itself, because the box is what blurs the picture behind it: a mask
// shapes an element's backdrop-filter along with it, where a blurred child of
// a masked box would have nothing to blur — a mask makes its element the
// backdrop root for everything in it, see placeFade. And a mask rather than a
// clip-path, which Chrome would not put on the blur alongside the hole's mask;
// styles.css intersects the two. The mask is an SVG mask element kept on the
// body, redrawn as the box changes: an image would be loaded afresh each
// time, asynchronously in Safari, and a box whose mask has not loaded is
// masked to nothing. Two of them per box, taking turns, since Safari also
// paints nothing for a box whose mask changed in place. What the mask costs is anything hanging
// outside the box, which is why the ⇧ ring is a sibling here, placed after
// the box whenever the box moves, changes class or changes size, and fading
// as the box fades, which inside the box it would do on its own. The hairline
// is the ring between the silhouette and the silhouette a device pixel in,
// cut from a box under the text; mask and ring are snapped to the device's
// pixels together, from where each engine puts the box's frame on them, so
// each takes whole pixels the way a CSS box's own edge and inset shadow do.
// styles.css lays the row out in the tab. The numbers are the app's
// at 30pt of text, in em of the box: 16pt corners on the pill and on the tab,
// and an 8pt foot, the concave curve where the tab's inner side flares into
// the pill's top.
const nameTab = (() => {
  if (typeof ResizeObserver !== 'function') return null;
  // On from the menu's Show Source App Name → Name Tab; off, the boxes
  // wear the header row and none of this runs.
  let on = false;
  const NS = 'http://www.w3.org/2000/svg';
  const CORNER = 0.533;
  const FOOT = 0.267;
  // The ⇧ ring's distance from the shape, and a margin past it for its line.
  const GROW = 3.5;
  const MARGIN = GROW + 1.5;

  // Which engine, for where a box's pixels fall. Each draws a mask, and a
  // clip-path, in the box's own frame, and each sits that frame differently
  // on the device's pixels: Blink keeps the box's fractional position and
  // wants the transform that centres it whole in device pixels; Gecko snaps
  // the frame to device pixels on its own; WebKit does too, and sits best
  // with the transform whole in CSS pixels. Measured one edge at a time in
  // all three, and only the engine tells them apart.
  const ENGINE = navigator.userAgentData ? 'blink'
    : (window.CSS && CSS.supports('-moz-appearance', 'none')) ? 'gecko' : 'webkit';

  // The element's own transform made whole in the pixels its engine wants:
  // whole device pixels for Blink, whole CSS pixels for WebKit, and nothing
  // for Gecko, which snaps on its own. Measured one edge at a time in all
  // three. The demos position a box by whole pixels and centre it with
  // translateX(-50%), half of whatever width the text gave it, so the
  // transform is the only fraction in where it lands. Written through the
  // translate property, which the demos never touch. (Correcting the whole
  // of where it lands, layout included, from its rect, put the stack's
  // boxes in Safari on a fraction instead, and changed nothing in Chrome.)
  const align = (el) => {
    if (ENGINE === 'gecko') return;
    const m = getComputedStyle(el).transform;
    let want = '';
    if (m && m !== 'none') {
      const t = new DOMMatrixReadOnly(m);
      const dpr = window.devicePixelRatio || 1;
      const fix = (v) => Math.round((ENGINE === 'blink'
        ? (Math.round(v * dpr) - v * dpr) / dpr : Math.round(v) - v) * 1000) / 1000;
      want = fix(t.e) + 'px ' + fix(t.f) + 'px';
    }
    // Compared as the engine gives it back: a trailing zero is dropped.
    const have = el.style.translate || '';
    if (have === want || have === want.replace(/ 0px$/, '') || !mayWrite(el)) return;
    el.style.translate = want;
  };

  // A write that changes how tall the stack's content is — a box's height
  // made whole, the gap made whole — after the demo has parked the stack at
  // its end: a scroller keeps its scrollTop through that, so the stack
  // drifts from its end by the change, and the last box's bottom edge goes
  // under the clip. Its distance from the end is kept instead. A stack
  // below the live box has its near end at the top, where scrollTop
  // already keeps it.
  const keepEnd = (stack, write) => {
    if (!stack || stack.classList.contains('is-below')) { write(); return; }
    const near = stack.scrollHeight - stack.clientHeight - stack.scrollTop;
    write();
    const top = stack.scrollHeight - stack.clientHeight - near;
    if (Math.abs(stack.scrollTop - top) > 0.01) stack.scrollTop = top;
  };

  // A box in the stack is centred by the stack's column, which puts it half
  // a pixel off whenever the stack is an odd number of pixels wider: it is
  // placed instead by a margin of whole pixels, from the stack's own edge,
  // which every engine paints where layout says. The gap between boxes is
  // made whole the same way, so each box's top is whole as well.
  const settle = (history) => {
    const dpr = window.devicePixelRatio || 1;
    const em = parseFloat(getComputedStyle(history).fontSize) || 16;
    const gap = Math.round(0.2 * em * dpr) / dpr + 'px';
    if (history.style.gap !== gap && mayWrite(history)) keepEnd(history, () => { history.style.gap = gap; });
    const inner = history.clientWidth;
    for (const el of history.children) {
      const st = boxes.get(el);
      if (!st) continue;
      // A box the search has hidden has no width to centre, and half the
      // stack's width written on it as a margin would be measured back into
      // the stack the next time the demo stands every box up to read its
      // width (paintHistory), which is what widened the pill with every
      // keystroke. Left where it was placed; it is placed again when it shows.
      if (!el.offsetWidth) continue;
      const m = Math.floor((inner - el.offsetWidth) * dpr / 2) / dpr + 'px';
      if (el.style.marginInlineStart !== m && mayWrite(el)) el.style.marginInlineStart = m;
    }
  };

  // A budget on writes to an element's style: the live box is redrawn on
  // every change to its style, and a redraw that always finds something to
  // write is a loop that never yields. A box being typed into wants two or
  // three writes a word, several words a second; a loop wants thousands, and
  // hits the budget at once. A write the budget refused is tried again once
  // the budget has passed, so nothing is left where it was.
  const writes = new WeakMap();
  const retries = new WeakSet();
  const mayWrite = (el) => {
    const now = performance.now();
    const recent = (writes.get(el) || []).filter((t) => now - t < 500);
    writes.set(el, recent);
    if (recent.length >= 40) {
      if (!retries.has(el)) {
        retries.add(el);
        setTimeout(() => { retries.delete(el); if (boxes.has(el)) draw(el); else align(el); }, 600);
      }
      return false;
    }
    recent.push(now);
    return true;
  };

  // The silhouette, as Pill.silhouette and Pill.tabPath trace it, in the box's
  // own pixels with y running down. W×H is the box, T the tab's height — the
  // pill's top edge — and X the tab's width, or nothing for a box with no tab;
  // R the corner and F the foot. `o` moves the path inward: a hairline for
  // the rim's inner edge, whose convex corners tighten and whose foot widens
  // by it, and negative for the ring outside. Traced with the tab on the
  // left, and mirrored for a right-to-left box, where every arc turns the
  // other way. `snap` puts every point on the device's pixels, and `shift`
  // moves the whole path up and left by that much, into the frame of a box
  // that starts there.
  const silhouette = (W, H, T, X, R, F, o, rtl, snap, shift) => {
    const r = Math.max(R - o, 0);
    const f = Math.max(F + o, 0);
    const x = rtl ? (v) => W - v : (v) => v;
    const cw = rtl ? 0 : 1;
    const ccw = 1 - cw;
    const n = (v) => Math.round(v * 100) / 100;
    const sx = snap ? snap.x : (v) => v;
    const sy = snap ? snap.y : (v) => v;
    const dx = shift ? shift[0] : 0;
    const dy = shift ? shift[1] : 0;
    const to = (px, py) => n(sx(x(px)) - dx) + ' ' + n(sy(py) - dy);
    const arc = (rad, sweep, px, py) => 'A' + n(rad) + ' ' + n(rad) + ' 0 0 ' + sweep + ' ' + to(px, py);
    const d = T > 0 && X > 0
      // From where the foot lands on the pill's top: up the foot, up the
      // tab's inner side, over its top and down its outer side into the
      // pill's, whose corner under the tab is square.
      ? ['M' + to(X + F, T + o), arc(f, cw, X - o, T - F), 'L' + to(X - o, R),
         arc(r, ccw, X - R, o), 'L' + to(R, o), arc(r, ccw, o, R)]
      : ['M' + to(R, o), arc(r, ccw, o, R)];
    // Down the pill's leading side, along its bottom, up its far side and
    // back along its top to where the tab's foot lands.
    d.push('L' + to(o, H - R), arc(r, ccw, R, H - o), 'L' + to(W - R, H - o),
           arc(r, ccw, W - o, H - R), 'L' + to(W - o, T + R), arc(r, ccw, W - R, T + o), 'Z');
    return d.join(' ');
  };

  // The mask's path: the silhouette, grown by `g` along the four outer sides
  // and round the three corners the box itself rounds, so that the box's own
  // edge, on whole pixels, is what cuts the fill, the blur and the box's
  // inset hairline there; and exact through the tab's inner corner — its
  // corner above, its inner side, the foot, the pill's top edge and the
  // corner at its end — which the box has no edge for. Grown and exact meet
  // in a step outside the box, where nothing is drawn.
  const maskPath = (W, H, T, X, R, F, g, rtl, snap) => {
    const x = rtl ? (v) => W - v : (v) => v;
    const cw = rtl ? 0 : 1;
    const ccw = 1 - cw;
    const n = (v) => Math.round(v * 100) / 100;
    const to = (px, py) => n(snap.x(x(px))) + ' ' + n(snap.y(py));
    const arc = (rad, sweep, px, py) => 'A' + n(rad) + ' ' + n(rad) + ' 0 0 ' + sweep + ' ' + to(px, py);
    const d = T > 0 && X > 0
      ? ['M' + to(X + F, T), arc(F, cw, X, T - F), 'L' + to(X, R), arc(R, ccw, X - R, 0),
         'L' + to(X - R, -g), 'L' + to(R - g, -g), arc(R, ccw, -g, R - g)]
      : ['M' + to(R - g, -g), arc(R, ccw, -g, R - g)];
    d.push('L' + to(-g, H - R + g), arc(R, ccw, R - g, H + g), 'L' + to(W - R + g, H + g),
           arc(R, ccw, W + g, H - R + g));
    if (T > 0 && X > 0) {
      d.push('L' + to(W + g, T + R), 'L' + to(W, T + R), arc(R, ccw, W - R, T), 'Z');
    } else {
      d.push('L' + to(W + g, R - g), arc(R, ccw, W - R + g, -g), 'Z');
    }
    return d.join(' ');
  };

  // The rim's path: the part of the hairline ring the box's own inset
  // hairline does not draw, and none of the part it does. The box's hairline
  // is a band `hair` wide inside its edges, cut by the mask along the tab's
  // corner and the pill's; the rim is the rest of the ring, which begins
  // where the tab's corner leaves that band and ends where the pill's
  // corner enters it, with straight cuts along the band's inner side, on a
  // pixel's edge, so the two meet without a pixel drawn twice. Out along
  // the outer edge, back along the inner.
  const rimPath = (W, H, T, X, R, F, hair, rtl, snap, shift) => {
    const r = Math.max(R - hair, 0);
    const f = F + hair;
    const x = rtl ? (v) => W - v : (v) => v;
    const cw = rtl ? 0 : 1;
    const ccw = 1 - cw;
    const n = (v) => Math.round(v * 100) / 100;
    const to = (px, py) => n(snap.x(x(px)) - shift[0]) + ' ' + n(snap.y(py) - shift[1]);
    const arc = (rad, sweep, px, py) => 'A' + n(rad) + ' ' + n(rad) + ' 0 0 ' + sweep + ' ' + to(px, py);
    // How far along the box's edge a corner's outer arc runs before it is
    // a hairline in from the edge.
    const run = Math.sqrt(Math.max(R * R - r * r, 0));
    return ['M' + to(X - R, hair), 'L' + to(X - R + run, hair), arc(R, cw, X, R),
            'L' + to(X, T - F), arc(F, ccw, X + F, T), 'L' + to(W - R, T), arc(R, cw, W - hair, T + R - run),
            'L' + to(W - hair, T + R), arc(r, ccw, W - R, T + hair), 'L' + to(X + F, T + hair),
            arc(f, cw, X - hair, T - F), 'L' + to(X - hair, R), arc(r, ccw, X - R, hair), 'Z'].join(' ');
  };

  const boxes = new Map();

  // Every box's mask element, in one SVG on the body: a mask inside the box
  // it masks is a reference to itself, and the box is drawn as nothing.
  let defs = null;
  const maskFor = (id) => {
    if (!defs) {
      defs = document.createElementNS(NS, 'svg');
      defs.setAttribute('class', 'ov-defs');
      defs.setAttribute('width', '0');
      defs.setAttribute('height', '0');
      defs.setAttribute('aria-hidden', 'true');
      document.body.append(defs);
    }
    const mask = document.createElementNS(NS, 'mask');
    mask.setAttribute('id', id);
    mask.setAttribute('maskUnits', 'userSpaceOnUse');
    mask.setAttribute('x', '0');
    mask.setAttribute('y', '0');
    defs.append(mask);
    return mask;
  };

  // The ring, on the box's containing block, where the box's own position is.
  const holder = (el) => {
    let p = el.parentElement;
    while (p && p !== document.body && getComputedStyle(p).position === 'static') p = p.parentElement;
    return p || document.body;
  };
  const place = (box) => {
    const st = boxes.get(box);
    if (!st || !st.trace) return;
    const on = box.classList.contains('is-movable');
    st.trace.classList.toggle('is-on', on);
    // Fading with the box, out as a line ends and back in with the next.
    st.trace.classList.toggle('is-visible', box.classList.contains('is-visible'));
    if (!on) return;
    const b = box.getBoundingClientRect();
    const h = holder(st.trace);
    const p = h.getBoundingClientRect();
    st.trace.style.left = (b.left - p.left - h.clientLeft - MARGIN) + 'px';
    st.trace.style.top = (b.top - p.top - h.clientTop - MARGIN) + 'px';
  };

  // A box whose size is a fraction of a device pixel has its far edges
  // drawn short of the silhouette drawn to its true size: Blink paints it
  // as if the fraction were not there, so the fill stops a pixel early on
  // the right and the mask with it, taking the ring and the tab's inner
  // side; WebKit and Gecko stretch it to whole pixels, and the ring on the
  // right lands across two. So a box is padded out to whole device pixels
  // on the right and at the bottom, the two sides its size runs to, by
  // less than a pixel, which no text notices. Written only when it changes:
  // the live box is redrawn on every change to its style, and a write on
  // every redraw is a loop.
  const whole = (box, st) => {
    if (st.raf) return;
    // The pixel a box's size is made whole in: the device's, except in
    // Blink, which draws a box's inset hairline two device pixels wide when
    // the box's far edge lands on half a CSS pixel.
    const dpr = ENGINE === 'blink' ? 1 : (window.devicePixelRatio || 1);
    const rect = box.getBoundingClientRect();
    const size = [rect.width, rect.height];
    if (!size[0] || !size[1]) return;
    const cs = getComputedStyle(box);
    // The floor under a short line, 4.67em, made whole first: padding cannot
    // widen a box that is already held at its floor. From the em, not the
    // computed floor, which once lifted is whole and would drop its lift.
    const floor = 4.67 * (parseFloat(cs.fontSize) || 16);
    const ff = ((floor * dpr) % 1 + 1) % 1;
    const lift = ff < 0.03 || ff > 0.97 ? 0 : Math.round((1 - ff) / dpr * 64) / 64;
    const want = { lift: lift ? 'calc(4.67em + ' + lift + 'px)' : '', pad: st.pad.slice() };
    // A box at its widest cannot be widened: padding it narrows its text
    // instead, the text wraps, the height changes, and the padding is
    // worked out again from the new size, every frame, for ever. Layout
    // keeps sixty-fourths of a pixel, so the padding is one of those, and
    // the box grows by exactly it; anything within a few hundredths of a
    // whole pixel is whole.
    const widest = size[0] >= (parseFloat(cs.maxWidth) || Infinity) - 0.05;
    for (let i = 0; i < 2; i++) {
      const natural = size[i] - st.pad[i];
      const f = ((natural * dpr) % 1 + 1) % 1;
      want.pad[i] = (i === 0 && widest) || f < 0.03 || f > 0.97 ? 0 : Math.round((1 - f) / dpr * 64) / 64;
    }
    const same = want.lift === st.lift && Math.abs(want.pad[0] - st.pad[0]) < 0.001
      && Math.abs(want.pad[1] - st.pad[1]) < 0.001;
    if (same || !mayWrite(box)) return;
    // On the next frame, not now: most redraws come from the resize observer,
    // and a size changed under it is a loop it reports on the console.
    st.raf = requestAnimationFrame(() => {
      st.raf = 0;
      st.lift = want.lift;
      st.pad = want.pad;
      keepEnd(box.closest('.demo-history'), () => {
        box.style.minWidth = want.lift;
        box.style.paddingRight = want.pad[0] ? 'calc(0.73em + ' + want.pad[0] + 'px)' : '';
        box.style.paddingBottom = want.pad[1] ? 'calc(0.47em + ' + want.pad[1] + 'px)' : '';
      });
    });
  };

  const draw = (box) => {
    const st = boxes.get(box);
    if (!st || !on || !box.classList.contains('is-tabbed')) return;
    // The live box carries the transform that centres it; a box in the
    // stack is placed by settle, from the stack's edge.
    if (st.trace) align(box);
    whole(box, st);
    const rect = box.getBoundingClientRect();
    const W = rect.width;
    const H = rect.height;
    if (!W || !H) return;
    const cs = getComputedStyle(box);
    const em = parseFloat(cs.fontSize) || 16;
    const tab = st.row && !st.row.hidden ? st.row.getBoundingClientRect() : null;
    const T = tab ? tab.height : 0;
    const X = tab ? tab.width : 0;
    const R = CORNER * em;
    const F = FOOT * em;
    const rtl = cs.direction === 'rtl';
    const hair = parseFloat(cs.getPropertyValue('--hairline')) || 1;
    // Onto the device's pixels, so the fill's edge and the hairline inside
    // it each take one whole pixel, the way the header row's inset shadow
    // does: from where the box's frame sits on them, which is its position
    // in Blink and a whole pixel in the others, see ENGINE.
    const dpr = window.devicePixelRatio || 1;
    const frac = (v) => ((v % 1) + 1) % 1;
    const fx = 0 * frac(rect.left * dpr);
    const fy = 0 * frac(rect.top * dpr);
    const snap = {
      x: (v) => (Math.round(fx + v * dpr) - fx) / dpr,
      y: (v) => (Math.round(fy + v * dpr) - fy) / dpr,
    };
    // Nothing to redraw for a box that only moved by whole pixels.
    const key = [W, H, T, X, fx, fy, rtl, hair, dpr].join(' ');
    if (st.key === key) {
      if (st.trace) place(box);
      return;
    }
    st.key = key;
    // Into whichever mask the box is not wearing, then the box is pointed
    // at it: Safari paints a box whose mask changes under it as nothing, and
    // paints one whose mask is exchanged for another every time.
    const next = st.masks[st.turn = 1 - st.turn];
    // The mask's region a pixel past the box all round: snapping can put an
    // edge half a pixel outside the box, and the region cuts what it holds.
    next.mask.setAttribute('x', '-1');
    next.mask.setAttribute('y', '-1');
    next.mask.setAttribute('width', W + 2);
    next.mask.setAttribute('height', H + 2);
    // Half a pixel proud of the box where the box has an edge of its own,
    // so that the edge, rounded corners and all, is what cuts the fill, the
    // blur and the stylesheet's inset hairline there, on whole pixels, as it
    // does the header row's box: a mask's far edges fall a fraction of a
    // pixel short of the box's, in every engine, and took the hairline with
    // them. Exact through the tab's inner corner, which the box has no edge
    // for and which was always drawn true.
    next.fill.setAttribute('d', maskPath(W, H, T, X, R, F, 0.5, rtl, snap));
    box.style.setProperty('--ov-shape', 'url(#' + next.mask.id + ')');
    // The rim. The box keeps the stylesheet's rounded corners and inset
    // hairline, as the header row has them, and the mask cuts that hairline
    // to the silhouette: it is the box's own edge, and every engine paints
    // that on whole pixels. What it cannot draw is the tab's inner corner —
    // the tab's inner side and its corner above, the foot, the pill's top
    // edge beside the tab and the corner at its end — and that much is the
    // ring between the silhouette and the silhouette a hairline in, cut
    // from a box of the line's colour that covers only that corner.
    if (T > 0 && X > 0) {
      // A box round the tab's inner corner, on whole pixels, where Safari
      // and Firefox put a box's frame; the path inside it is what draws.
      const x0 = rtl ? 0 : Math.max(Math.floor(X - R - 2), 0);
      const x1 = rtl ? Math.min(Math.ceil(W - X + R + 2), W) : W;
      const y1 = Math.min(Math.ceil(T + R + 2), H);
      st.rim.style.display = '';
      st.rim.style.left = x0 + 'px';
      st.rim.style.top = '0px';
      st.rim.style.width = (x1 - x0) + 'px';
      st.rim.style.height = y1 + 'px';
      st.rim.style.clipPath = 'path("' + rimPath(W, H, T, X, R, F, hair, rtl, snap, [x0, 0]) + '")';
    } else {
      st.rim.style.display = 'none';
    }
    if (!st.trace) return;
    const w = W + MARGIN * 2;
    const h = H + MARGIN * 2;
    st.trace.setAttribute('viewBox', -MARGIN + ' ' + -MARGIN + ' ' + w + ' ' + h);
    st.trace.style.width = w + 'px';
    st.trace.style.height = h + 'px';
    const d = silhouette(W, H, T, X, R, F, -GROW, rtl);
    st.trace.querySelectorAll('path').forEach((path) => path.setAttribute('d', d));
    place(box);
  };

  // Once per box per frame, whether the box or its row changed size.
  const sizes = new ResizeObserver((entries) => {
    const seen = new Set();
    entries.forEach((entry) => {
      const box = entry.target.closest('.is-tabbed');
      if (box && !seen.has(box)) { seen.add(box); draw(box); }
    });
  });
  // A move is a redraw, since where the box sits decides the snapping; a
  // move by whole pixels costs a key comparison.
  const moves = new MutationObserver((records) => records.forEach((r) => draw(r.target)));
  window.addEventListener('resize', () => boxes.forEach((st, box) => { if (box.isConnected) draw(box); }));

  // The class goes on every time, not only the first: a box that has been
  // through Off or Header Row since (undress takes it off) is the same box
  // with the same masks, and comes back to the tab as it went.
  const dress = (box) => {
    box.classList.add('is-tabbed');
    let st = boxes.get(box);
    if (st) return st;
    const rim = document.createElement('span');
    rim.className = 'ov-rim';
    rim.setAttribute('aria-hidden', 'true');
    box.prepend(rim);
    // The masks, two to take turns: white where the box is, in the box's
    // own pixels — an SVG mask is luminance by default — and the box names
    // one by its bare fragment, which Safari takes from a stylesheet's rule
    // as a reference into this document where it takes the page's own
    // absolute URL with the fragment as nothing at all.
    const masks = ['a', 'b'].map((side) => {
      const mask = maskFor('ov-shape-' + (boxes.size + 1) + side);
      const fill = document.createElementNS(NS, 'path');
      fill.setAttribute('fill', '#fff');
      mask.append(fill);
      return { mask: mask, fill: fill };
    });
    st = { row: box.querySelector('.ov-app'), rim: rim, masks: masks, turn: 0, trace: null, key: '',
           pad: [0, 0], lift: '', raf: 0 };
    boxes.set(box, st);
    sizes.observe(box);
    if (st.row) sizes.observe(st.row);
    return st;
  };

  // A box back to a plain pill, or a header row: its classes off, its rim
  // and its ring hidden. Its masks stay, unreferenced, for the next time;
  // what it was last drawn as does not, so that the next draw draws it
  // whole, rim and ring with it, even at the size it left at.
  const undress = (box) => {
    const st = boxes.get(box);
    box.classList.remove('is-tabbed', 'has-tab');
    if (!st) return;
    st.key = '';
    st.rim.style.display = 'none';
    if (st.trace) st.trace.classList.remove('is-on', 'is-visible');
  };

  return {
    get on() { return on; },
    enable: (flag) => {
      on = !!flag;
      if (!on) boxes.forEach((st, box) => undress(box));
    },
    // The stack's boxes, after the stack has been laid out: the stack's
    // centring transform made whole, and every box redrawn where it sits.
    refresh: (history) => {
      if (!on) return;
      align(history);
      settle(history);
      if (!history.dataset.ovRise) {
        // A box rises into the stack on a transform of its own; once it
        // has landed, it is placed again from where it landed.
        history.dataset.ovRise = '1';
        history.addEventListener('animationend', (e) => { if (boxes.has(e.target)) draw(e.target); });
      }
      for (const el of history.children) if (boxes.has(el)) draw(el);
    },
    // `tab` is whether the box has an app to name; without one it is a plain
    // pill, clipped all the same.
    wear: (box, tab) => {
      if (!on) { undress(box); return; }
      dress(box);
      box.classList.toggle('has-tab', tab);
      draw(box);
    },
    ring: (box) => {
      const st = dress(box);
      if (st.trace) return;
      const svg = document.createElementNS(NS, 'svg');
      svg.setAttribute('class', 'ov-trace');
      svg.setAttribute('aria-hidden', 'true');
      ['ring-white', 'ring-black'].forEach((tone) => {
        const path = document.createElementNS(NS, 'path');
        path.setAttribute('class', tone);
        svg.append(path);
      });
      box.after(svg);
      st.trace = svg;
      moves.observe(box, { attributes: true, attributeFilter: ['style', 'class'] });
      draw(box);
    },
  };
})();

// Show Source App Name, as the menu has it: the header row, the site's
// default; the tab, see nameTab; or off.
// `dressBox` puts a box in the current style, from whether it has an app to
// name; `setIconStyle` puts every box on the page in a new one.
let ICON_STYLE = 'header';
const dressBox = (box, named) => {
  const row = box.querySelector('.ov-app');
  if (row) row.hidden = !named || ICON_STYLE === 'off';
  if (nameTab) nameTab.wear(box, named && ICON_STYLE === 'nameTab');
  // A box that rings under ⇧ rings in the new style too.
  if (nameTab && nameTab.on && box.querySelector('.ov-ring')) nameTab.ring(box);
};
const setIconStyle = (style) => {
  if (ICON_STYLE === style) return;
  ICON_STYLE = style;
  if (nameTab) nameTab.enable(style === 'nameTab');
  document.querySelectorAll('.demo-overlay, .hist-line').forEach((box) => dressBox(box, box.dataset.named === '1'));
  if (nameTab && nameTab.on) document.querySelectorAll('.demo-history').forEach((h) => nameTab.refresh(h));
};

// What a demo runs on before it is seeded, see SETTINGS: the app's defaults
// where the demo already drew them, and the demo's own where it differs. The
// stack keeps fifteen boxes, not the app's every box, since a loop that
// repeats seven lines would stack hundreds of them; it never forgets them,
// since the loop never falls silent; and a box holds its whole sentence,
// however many lines, rather than paging at the app's two. A demo passes
// what is its own on top (the landing pages start with the reveal off).
const DEMO_DEFAULTS = {
  fontSize: 30, textAlignment: 'start', iconStyle: 'header', maxLines: Infinity,
  boxOpacity: 0.72, blur: 6,
  revealEnabled: true, revealOpacity: 0.95, revealWidth: 800, revealHeight: 400,
  historyEnabled: true, historyDepth: 15, historyTextOpacity: 0.65,
  historyExpires: false, historyExpiry: 30,
  bothLanguages: false, microphone: false,
  borealis: 'rainbow', borealisStrength: 'medium',
  theme: 'auto',
};
// Color Theme: the boxes' colors for a chosen theme, as the stylesheet's two
// palettes state them (--box-rgb, --ink-rgb, --box-name and --pill-line under
// .demo in styles.css), restated here so a pick can write the other palette's
// box over the page's. Auto has no entry: the page's own tokens stand.
const BOX_THEMES = {
  light: ['255 255 255', '62 62 66', 'rgb(0 0 0 / 0.55)', 'rgb(0 0 0 / 0.08)'],
  dark: ['0 0 0', '255 255 255', '#d2d2d3', 'rgb(210 210 211 / 0.16)'],
};
const BOX_TOKENS = ['--box-rgb', '--ink-rgb', '--box-name', '--pill-line'];
// A demo's boxes dressed to its settings. What is the box's rather than the
// loop's goes onto the screen as custom properties, which every box on it
// wears, the stack's and the search pill with the live one; the loop reads
// the rest off S itself. Once at the seed, and again whenever S changes.
const dressDemo = (screen, S) => {
  if (screen) {
    const set = (name, value) => screen.style.setProperty(name, String(value));
    set('--text-scale', S.fontSize / 30);
    set('--text-align', S.textAlignment);
    set('--box-alpha', S.boxOpacity);
    set('--box-blur', S.blur + 'px');
    set('--hole-strength', S.revealOpacity);
    // The hole's radii, in em of the box at the app's 30pt: its 800 × 400
    // are 13.33 × 6.67em.
    set('--hole-w', (S.revealWidth / 60).toFixed(3) + 'em');
    set('--hole-h', (S.revealHeight / 60).toFixed(3) + 'em');
    set('--hist-text-alpha', S.historyTextOpacity);
    // The boxes' colors: the chosen palette's over the page's, or, on Auto,
    // nothing of their own, so the page's tokens show through again.
    const theme = BOX_THEMES[S.theme];
    BOX_TOKENS.forEach((name, i) => {
      if (theme) screen.style.setProperty(name, theme[i]);
      else screen.style.removeProperty(name);
    });
  }
  setIconStyle(S.iconStyle);
};
// A demo's settings, its own under the page's seed, and its boxes dressed to
// them.
const seedDemo = (screen, own) => {
  const S = Object.assign({}, DEMO_DEFAULTS, own, SETTINGS);
  dressDemo(screen, S);
  return S;
};
// The menu's checks for a demo's settings: the size row within half a point
// of the size, as the app's menu checks it, and none for any other size.
const menuChecks = (S) => {
  const size = [22, 30, 40, 52].find((pt) => Math.abs(pt - S.fontSize) < 0.5);
  const on = (id, flag) => (flag ? id : null);
  return {
    checked: ['size-' + (size || 'none'), 'align-' + S.textAlignment,
      { off: 'icon-off', nameTab: 'icon-tab', header: 'icon-header' }[S.iconStyle],
      'audio-' + (S.microphone ? 'mic' : 'all'),
      'borealis-' + S.borealis, 'glow-' + S.borealisStrength, 'theme-' + S.theme,
      on('reveal', S.revealEnabled), on('history', S.historyEnabled),
      on('both', S.bothLanguages)].filter(Boolean),
    unchecked: [on('reveal', !S.revealEnabled), on('history', !S.historyEnabled),
      on('both', !S.bothLanguages)].filter(Boolean),
  };
};
// How many lines a box's text takes, for the app's maxLines: the text block's
// height in its own line-height, read once the words are in the page. `part`
// is the block to read, the caption by default; the other language under it
// counts on its own, in its own smaller line, since the app turns the page
// when either paragraph fills.
const linesOf = (box, part) => {
  const text = part || textOf(box);
  const cs = getComputedStyle(text);
  const line = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2334;
  return Math.round(text.getBoundingClientRect().height / line);
};
// Whether a box has more lines than the app's maxLines allows, in either
// of its paragraphs.
const overflows = (box, maxLines) => {
  if (linesOf(box) > maxLines) return true;
  const under = box.querySelector('.ov-under');
  return !!(under && under.firstChild) && linesOf(box, under) > maxLines;
};
// The words of `text` from `from` up to `to`, counted in a line `of` words
// long: a page of the line itself, or the same stretch of its source, which
// is not the same length and is taken as a fraction of it, as the demos
// draw the source under ⌃.
const pageOf = (text, from, to, of) => {
  const words = text.split(' ');
  const at = (k) => (of === words.length ? k : Math.round((k / of) * words.length));
  const start = Math.min(at(from), words.length - 1);
  return words.slice(start, Math.max(start + 1, at(to))).join(' ');
};

// The pointer reveal: where the pointer is over the screen, kept in the
// page's coordinates rather than as the hole's offset, because the box moves
// under a still pointer far more than the pointer moves over a still box:
// it re-centres and re-sizes on every word, and the app recomputes the
// centre on exactly the same events for the same reason. One paint a frame
// at most: the box resizes on every word and the pointer reports faster
// than that, so both feed the same queue, and `onFrame` runs with it, for
// whatever else follows the box. `solid` says when the box stays whole:
// under ⇧, since you are about to pick it up, and under ⌥, since the stack
// is what is being read then. `on` is the menu's Fade Away Under Pointer.
const pointerReveal = (box, screen, opts) => {
  let on = opts.on !== false;
  let pointer = null;
  let queued = false;
  const paint = () => {
    if (!on || !pointer || opts.solid()) {
      box.style.setProperty('--hole-x', '-999px');
      box.style.setProperty('--hole-y', '-999px');
      return;
    }
    const rect = box.getBoundingClientRect();
    box.style.setProperty('--hole-x', (pointer.x - rect.left) + 'px');
    box.style.setProperty('--hole-y', (pointer.y - rect.top) + 'px');
  };
  const queue = () => {
    if (queued) return;
    queued = true;
    requestAnimationFrame(() => {
      queued = false;
      paint();
      opts.onFrame();
    });
  };
  if (screen) {
    screen.addEventListener('pointermove', (event) => {
      if (event.pointerType !== 'mouse') return;
      pointer = { x: event.clientX, y: event.clientY };
      queue();
    });
    // Nothing to turn off: the falloff means distance alone ends the reveal,
    // on this screen as on a real one. This is only for the pointer that
    // leaves in one jump, or out of the window entirely.
    screen.addEventListener('pointerleave', () => { pointer = null; queue(); });
  }
  // The box changes width on almost every word, which moves its left edge
  // by most of the box. Without this the hole lands off the pointer until
  // the pointer next moves, and reads as the reveal blinking out. Placed
  // here and now, not on the next frame: a resize callback runs after
  // layout and before the frame is painted, so the frame the box grows in
  // already has the hole under the pointer; `queue` still runs `onFrame`.
  if (typeof ResizeObserver === 'function') new ResizeObserver(() => { paint(); queue(); }).observe(box);
  box.classList.toggle('has-reveal', on);
  return {
    queue: queue,
    enable: (flag) => { on = !!flag; box.classList.toggle('has-reveal', on); queue(); },
  };
};

// The app's status menu, opened by hand: a click on the glyph drops it, and
// it works as a menu does — rows light under the pointer, a row with a
// submenu opens it, submenus nest (Language / Models has English inside it),
// a click outside or on the glyph takes it down, Escape too. The rows the
// demo can act on wear a Try badge and do what they say; the rest shake
// their heads, small and quick, the way the changelog's pills refuse a
// click, and the menu stays up. Listen To is filled each time it opens from
// the demo's windows, the way the app reads Core Audio each time. The demos
// also walk the menu themselves to switch translation on: that walk opens
// the menu if it is down and takes it down after, but a menu the visitor
// has up stays up.
const statusMenu = {
  attach: (opts) => {
    const root = opts.root;
    const glyph = opts.glyph;
    if (!root) return null;
    const subFor = (row) => (row.dataset.id ? root.querySelector('.mn-sub[data-for="' + row.dataset.id + '"]') : null);
    const enabled = (row) => !!row.querySelector(':scope > .mn-demo');
    // A panel's rows live in a scrolling holder, its first child, see below.
    const holder = (panel) => panel.firstElementChild;
    const panelOf = (el) => el.parentElement.closest('.mn-panel');
    const rows = (panel) => [...holder(panel).children].filter((el) => el.classList.contains('mn-row'));
    const rowFor = (id) => root.querySelector('.mn-row[data-id="' + id + '"]');
    root.querySelectorAll('.mn-demo').forEach((b) => { b.textContent = opts.badge; });
    // The checks, from the demo's state: a toggle on or off, a choice among
    // its group, which shares its prefix.
    const check = (id, on) => { const row = rowFor(id); if (row) row.classList.toggle('is-on', on); };
    // A choice with no row, a size off the menu's four, clears its group, as
    // the app's menu shows nothing checked for a size typed on the command line.
    const pick = (id) => {
      const group = id.slice(0, id.indexOf('-') + 1);
      root.querySelectorAll('.mn-row[data-id^="' + group + '"]').forEach((r) => {
        r.classList.toggle('is-on', r.dataset.id === id);
      });
    };
    const setChecks = (checks) => {
      (checks.checked || []).forEach((id) => (id.includes('-') ? pick(id) : check(id, true)));
      (checks.unchecked || []).forEach((id) => check(id, false));
    };
    setChecks(opts);

    let manual = false;
    let walking = null;
    // The last source picked in Listen To that was not the microphone.
    let lastAudio = null;
    const track = [];
    const subs = [...root.querySelectorAll('.mn-sub')];
    const panels = [root, ...subs];
    // A panel the screen leaves no room for scrolls inside itself, as a
    // macOS menu taller than the screen does: its rows go into a holder
    // capped to the room there is, and a chevron at either end, on the
    // panel's own glass, scrolls them under the pointer until that end
    // shows. The holder ends where a chevron's band begins, so the rows are
    // clipped there and the band is nothing but the panel, rim and all. A
    // submenu stays a child of the panel, beside the holder, positioned off
    // the panel as before, so the holder never clips it.
    const CHEVRON = '<svg viewBox="0 0 10 6" aria-hidden="true"><path d="M1 1l4 4 4-4" fill="none" stroke="currentColor" stroke-width="1.4" stroke-linecap="round" stroke-linejoin="round"/></svg>';
    panels.forEach((panel) => {
      const wrap = document.createElement('div');
      wrap.className = 'mn-scroll';
      [...panel.children].forEach((el) => { if (!el.classList.contains('mn-sub')) wrap.appendChild(el); });
      panel.insertBefore(wrap, panel.firstChild);
      ['up', 'down'].forEach((dir) => {
        const band = document.createElement('div');
        band.className = 'mn-arrow is-' + dir;
        band.innerHTML = CHEVRON;
        panel.appendChild(band);
      });
    });
    const screen = root.closest('.demo-screen') || root.offsetParent;
    // How close to the screen's edge a panel may come: a padding and a half.
    const margin = () => 1.5 * parseFloat(getComputedStyle(root).paddingTop);
    // The room each panel has, in px, once `fit` has found it short of it.
    const rooms = new Map();
    const bandOf = (panel, dir) => panel.querySelector(':scope > .is-' + dir);
    // The holder's box and the chevrons, from the room there is and how far
    // the rows have gone up: a chevron takes its band off the holder's end
    // while there is more to see that way. The top band coming and going
    // moves the holder's top edge, and the scroll position moves with it,
    // so the rows themselves stay put.
    const layout = (panel) => {
      const wrap = holder(panel);
      const room = rooms.get(panel);
      const up = bandOf(panel, 'up');
      const down = bandOf(panel, 'down');
      // A holder scrolls only while its panel is short of room: otherwise
      // it is not a scroll container at all, so a trackpad cannot rubber-band
      // a menu that fits.
      panel.classList.toggle('is-capped', !!room);
      if (!room) {
        panel.style.height = '';
        wrap.style.maxHeight = '';
        wrap.style.marginTop = '';
        up.classList.remove('is-shown');
        down.classList.remove('is-shown');
        return;
      }
      const band = up.offsetHeight;
      const pad = parseFloat(getComputedStyle(panel).paddingTop);
      const gone = wrap.scrollTop - (up.classList.contains('is-shown') ? band : 0);
      const showUp = gone > 0;
      const showDown = gone + room < wrap.scrollHeight - 1;
      // The panel holds its full room, so the holder ends a band short of
      // its bottom edge rather than the panel ending with the holder.
      panel.style.height = room + 'px';
      wrap.style.maxHeight = (room - (showUp ? band : 0) - (showDown ? band : 0)) + 'px';
      wrap.style.marginTop = showUp ? (band - pad) + 'px' : '';
      const want = Math.max(0, gone) + (showUp ? band : 0);
      if (Math.abs(wrap.scrollTop - want) > 0.5) wrap.scrollTop = want;
      up.classList.toggle('is-shown', showUp);
      down.classList.toggle('is-shown', showDown);
    };
    // The panel kept inside the screen. One that may move (a submenu) goes
    // up first, as far as the top; what still does not fit scrolls.
    const fit = (panel, movable) => {
      const wrap = holder(panel);
      panel.style.height = '';
      wrap.style.maxHeight = '';
      wrap.style.marginTop = '';
      rooms.set(panel, 0);
      if (!screen) { layout(panel); return; }
      const s = screen.getBoundingClientRect();
      const m = margin();
      let r = panel.getBoundingClientRect();
      if (movable && r.bottom > s.bottom - m) {
        // No higher than the menu's own top: under the menu bar, as macOS keeps it.
        const up = Math.min(r.bottom - (s.bottom - m), r.top - root.getBoundingClientRect().top);
        if (up > 0) {
          panel.style.top = (parseFloat(panel.style.top) - up) + 'px';
          r = panel.getBoundingClientRect();
        }
      }
      const room = s.bottom - m - r.top;
      if (r.height > room) rooms.set(panel, room);
      layout(panel);
    };
    // The holder scrolled so the row shows whole.
    const reveal = (row) => {
      const panel = panelOf(row);
      const wrap = holder(panel);
      if (!rooms.get(panel)) return;
      const w = wrap.getBoundingClientRect();
      const r = row.getBoundingClientRect();
      if (r.top < w.top) wrap.scrollTop -= w.top - r.top;
      else if (r.bottom > w.bottom) wrap.scrollTop += r.bottom - w.bottom;
      layout(panel);
    };
    // The submenus under `panel` close, but for `keep` and the ones on the
    // way down to it. A submenu closing takes its lights with it and goes
    // back to its top, so it opens dark and whole next time.
    const closeSubs = (keep, panel = root) => subs.forEach((s) => {
      if (s === panel || !panel.contains(s) || s === keep || (keep && s.contains(keep))) return;
      s.classList.remove('is-open');
      holder(s).scrollTop = 0;
      s.querySelectorAll('.mn-row.is-hot').forEach((r) => r.classList.remove('is-hot'));
    });
    const cool = () => root.querySelectorAll('.mn-row.is-hot').forEach((r) => r.classList.remove('is-hot'));
    // Listen To, as the app builds it on each opening: the source, then what
    // is playing now with a dot, then the other apps that could be. The
    // demo says which from its windows, see `audio` in the callers.
    const listen = (sub) => {
      if (!opts.audio) return;
      sub.querySelectorAll('.is-live').forEach((el) => el.remove());
      const apps = opts.audio();
      const add = (cls, text) => {
        const el = document.createElement('div');
        el.className = cls + ' is-live';
        if (text !== undefined) {
          el.innerHTML = '<span class="mn-check">✓</span><span class="mn-label"></span>';
          el.lastChild.textContent = text;
        }
        holder(sub).appendChild(el);
      };
      const group = (title, list, mark) => {
        if (!list.length) return;
        add('mn-sep');
        add('mn-row is-dim', title);
        list.forEach((a) => add('mn-row', a.name + mark));
      };
      group('Playing now', apps.filter((a) => a.playing), ' ●');
      group('Other audio apps', apps.filter((a) => !a.playing), '');
    };
    // And it follows the demo while it is up: a window fronted or the sound
    // handed over shows in the windows' classes, and the rows redraw.
    if (opts.watch) {
      const live = new MutationObserver(() => {
        const sub = root.querySelector('.mn-sub[data-for="listen"].is-open');
        if (sub) { listen(sub); place(sub, rowFor('listen')); }
      });
      opts.watch.forEach((w) => live.observe(w, { attributes: true, attributeFilter: ['class'] }));
    }
    // The submenu hangs off its row, its first item level with it, and is
    // then kept on the screen, see `fit`. A submenu's submenu opens to the
    // right, over the menu, and to the left instead when the screen's edge
    // leaves it no room there, as macOS places it; one with no room either
    // side slides back inside, over what it must.
    const place = (sub, row) => {
      const panel = panelOf(row);
      sub.style.top = (row.getBoundingClientRect().top - panel.getBoundingClientRect().top
        - parseFloat(getComputedStyle(sub).paddingTop)) + 'px';
      sub.style.translate = '';
      sub.classList.remove('is-left');
      fit(sub, true);
      if (!screen) return;
      const s = screen.getBoundingClientRect();
      const m = margin();
      if (panel !== root && sub.getBoundingClientRect().right > s.right - m) sub.classList.add('is-left');
      const r = sub.getBoundingClientRect();
      const shift = r.left < s.left + m ? s.left + m - r.left : r.right > s.right - m ? s.right - m - r.right : 0;
      if (shift) sub.style.translate = shift + 'px 0';
    };
    const openSub = (row) => {
      const sub = subFor(row);
      if (!sub) return null;
      closeSubs(sub);
      rows(panelOf(row)).forEach((r) => { if (r !== row) r.classList.remove('is-hot'); });
      row.classList.add('is-hot');
      if (sub.dataset.for === 'listen') listen(sub);
      if (!sub.classList.contains('is-open')) track.length = 0;
      sub.classList.add('is-open');
      place(sub, row);
      return sub;
    };
    const open = (byHand) => {
      root.classList.add('is-open');
      fit(root, false);
      if (!byHand) return;
      manual = true;
      root.classList.add('is-manual');
      if (glyph) glyph.classList.add('is-menu');
    };
    const close = () => {
      manual = false;
      clearTimeout(aim);
      aim = 0;
      track.length = 0;
      root.classList.remove('is-open', 'is-manual');
      holder(root).scrollTop = 0;
      if (glyph) glyph.classList.remove('is-menu');
      closeSubs(null);
      cool();
    };
    // Taken down by the visitor while a walk is on: the walk finishes its
    // business without the menu.
    const dismiss = () => { if (walking) walking.cancelled = true; close(); };
    const refuse = (row) => {
      row.classList.remove('is-refused');
      void row.offsetWidth;
      row.classList.add('is-refused');
      setTimeout(() => row.classList.remove('is-refused'), 500);
    };
    const act = (row) => {
      const id = row.dataset.id || '';
      const a = opts.actions || {};
      if (id.startsWith('size-')) { pick(id); if (a.size) a.size(Number(id.slice(5))); }
      else if (id.startsWith('align-')) { pick(id); if (a.align) a.align(id.slice(6)); }
      else if (id.startsWith('icon-')) { pick(id); if (a.icon) a.icon(id.slice(5)); }
      // Listen To: all system audio or the microphone, a choice like the
      // sizes; the apps' rows, built on each opening, have no id and shake.
      // The microphone is a toggle as well: picked while it is the source,
      // it hands back to the source picked before it, or all system audio
      // when nothing was.
      else if (id.startsWith('audio-')) {
        let want = id;
        if (id === 'audio-mic' && row.classList.contains('is-on')) want = lastAudio || 'audio-all';
        else if (id !== 'audio-mic') lastAudio = id;
        pick(want);
        if (a.listen) a.listen(want.slice(6));
      }
      else if (id === 'reveal' || id === 'history' || id === 'both') {
        const on = !row.classList.contains('is-on');
        row.classList.toggle('is-on', on);
        if (a[id]) a[id](on);
      }
      // Audio Borealis: the look, Off among them, and the strength, each a
      // choice among its group.
      else if (id.startsWith('borealis-')) { pick(id); if (a.borealis) a.borealis(id.slice(9)); }
      else if (id.startsWith('glow-')) { pick(id); if (a.glow) a.glow(id.slice(5)); }
      // Color Theme: auto, light or dark, a choice among the three.
      else if (id.startsWith('theme-')) { pick(id); if (a.theme) a.theme(id.slice(6)); }
      else if (id === 'reset' && a.reset) a.reset();
    };
    const settle = (row) => {
      const panel = panelOf(row);
      rows(panel).forEach((r) => { if (r !== row) r.classList.remove('is-hot'); });
      if (row.classList.contains('is-dim')) { closeSubs(null, panel); return; }
      row.classList.add('is-hot');
      if (subFor(row)) openSub(row);
      else closeSubs(null, panel);
    };
    // The pointer on its way to an open submenu crosses the rows between,
    // and macOS gives it the benefit of the doubt: while it is heading for
    // the submenu, the row it is crossing is not taken as the one it wants.
    // Heading for it means that, going as it goes, it would cross the
    // submenu's near edge within the next half second. Once it stops,
    // slows or turns away, the row is taken. Heading and pace are read
    // from its last tenth of a second on the move (`track`, above), and
    // the pace is what tells a pointer going for the submenu from one
    // wandering down the rows a little sideways: that one would cross the
    // edge too, a second or two on, and is on a row it wants long before.
    let hovered = null;
    let aim = 0;
    const sample = (e) => {
      const now = performance.now();
      track.push({ x: e.clientX, y: e.clientY, t: now });
      // The last tenth of a second, and one sample from before it.
      while (track.length > 2 && now - track[1].t > 100) track.shift();
    };
    root.addEventListener('pointermove', (e) => { if (manual) sample(e); });
    const within = (sub) => {
      const now = track[track.length - 1];
      const r = sub.getBoundingClientRect();
      return !!now && now.x >= r.left && now.x <= r.right && now.y >= r.top && now.y <= r.bottom;
    };
    const toward = (sub) => {
      if (track.length < 2) return false;
      const now = track[track.length - 1];
      const from = track[0];
      const dx = now.x - from.x;
      const dy = now.y - from.y;
      if (Math.abs(dx) < 2 && Math.abs(dy) < 2) return false;
      // How long the pointer took over that: the time between samples,
      // each stretch capped at about a frame, since no event comes while
      // it rests, and a pointer that rested on a row and then set off is
      // going at the pace it set off at, not at the rest's.
      let dt = 0;
      for (let i = 1; i < track.length; i++) dt += Math.min(track[i].t - track[i - 1].t, 20);
      if (dt <= 0) return false;
      if (within(sub)) return true;
      const r = sub.getBoundingClientRect();
      // The near edge is the one that faces the row the submenu hangs off.
      const near = Math.abs(now.x - r.right) < Math.abs(now.x - r.left) ? r.right : r.left;
      // When it would reach that edge: never, going away from it or along
      // it; too late to count, at a crawl.
      const when = (near - now.x) / dx * dt;
      if (!(when > 0) || when > 500) return false;
      const y = now.y + (dy / dx) * (near - now.x);
      return y >= r.top - 6 && y <= r.bottom + 6;
    };
    root.addEventListener('pointerover', (e) => {
      if (!manual) return;
      const row = e.target.closest('.mn-row');
      if (!row || !root.contains(row)) return;
      sample(e);
      hovered = row;
      clearTimeout(aim);
      aim = 0;
      // The open submenu of the panel this row is in, if it has one.
      const panel = panelOf(row);
      const sub = subs.find((s) => panelOf(s) === panel && s.classList.contains('is-open'));
      if (sub && subFor(row) !== sub && toward(sub)) {
        const later = () => {
          aim = 0;
          if (hovered !== row) return;
          // Made it, and resting on the submenu's padding or a separator
          // rather than a row, which would have taken over: it stays.
          if (within(sub)) return;
          const still = performance.now() - track[track.length - 1].t < 250 && toward(sub);
          if (still) aim = setTimeout(later, 150);
          else settle(row);
        };
        aim = setTimeout(later, 300);
        return;
      }
      settle(row);
    });
    // The pointer resting on a band scrolls the rows past it, a few a
    // second, until that end shows and the band goes. The wheel scrolls
    // them too, and either way the row's submenu, if one was up, goes down.
    let rolling = 0;
    const stopRoll = () => { cancelAnimationFrame(rolling); rolling = 0; };
    const roll = (panel, band) => {
      const wrap = holder(panel);
      const dir = band.classList.contains('is-up') ? -1 : 1;
      const pace = 6 * 2 * parseFloat(getComputedStyle(root).fontSize) / 1000;  // six rows a second
      stopRoll();
      closeSubs(null, panel);
      rows(panel).forEach((r) => r.classList.remove('is-hot'));
      let last = performance.now();
      const step = (now) => {
        wrap.scrollTop += dir * (now - last) * pace;
        last = now;
        layout(panel);
        if (band.classList.contains('is-shown')) rolling = requestAnimationFrame(step);
        else rolling = 0;
      };
      rolling = requestAnimationFrame(step);
    };
    panels.forEach((panel) => {
      holder(panel).addEventListener('scroll', () => layout(panel));
      holder(panel).addEventListener('wheel', () => { if (manual) closeSubs(null, panel); }, { passive: true });
      panel.querySelectorAll(':scope > .mn-arrow').forEach((band) => {
        band.addEventListener('pointerenter', () => { if (manual) roll(panel, band); });
        band.addEventListener('pointerleave', stopRoll);
      });
    });
    window.addEventListener('resize', () => {
      if (!root.classList.contains('is-open')) return;
      fit(root, false);
      subs.forEach((sub) => {
        const row = sub.classList.contains('is-open') && rowFor(sub.dataset.for);
        if (row) place(sub, row);
      });
    });
    root.addEventListener('pointerleave', () => {
      if (!manual) return;
      // The row whose submenu is open keeps its light, as macOS keeps it.
      root.querySelectorAll('.mn-row.is-hot').forEach((r) => {
        const sub = subFor(r);
        if (!(sub && sub.classList.contains('is-open'))) r.classList.remove('is-hot');
      });
    });
    root.addEventListener('click', (e) => {
      if (!manual) return;
      const row = e.target.closest('.mn-row');
      if (!row || !root.contains(row) || row.classList.contains('is-dim')) return;
      if (subFor(row)) { openSub(row); return; }
      if (!enabled(row)) { refuse(row); return; }
      act(row);
      close();
    });
    if (glyph) glyph.addEventListener('click', (e) => {
      e.stopPropagation();
      if (root.classList.contains('is-open')) dismiss();
      else open(true);
    });
    document.addEventListener('pointerdown', (e) => {
      if (!manual) return;
      if (root.contains(e.target) || (glyph && glyph.contains(e.target))) return;
      dismiss();
    }, true);
    window.addEventListener('keydown', (e) => { if (e.key === 'Escape' && manual) dismiss(); });

    return {
      // A walk by the demo: the menu opened if it is down, and taken down
      // after — unless the visitor had it up, when it stays, its submenu
      // closed and its rows cooled. `cancelled` once the visitor takes it
      // down mid-walk: the walk then does its business without the menu.
      walk: () => {
        const w = { cancelled: false };
        if (!root.classList.contains('is-open')) open(false);
        walking = w;
        w.hot = (row) => { reveal(row); row.classList.add('is-hot'); };
        w.cool = (row) => row.classList.remove('is-hot');
        w.sub = (row) => openSub(row);
        w.end = () => {
          if (walking === w) walking = null;
          if (w.cancelled) return;
          if (manual) { closeSubs(null); cool(); } else close();
        };
        return w;
      },
      // The demos' own take-down, on a scene change: a menu the visitor has
      // up is theirs to take down.
      closeScripted: () => { if (!manual) close(); },
      // The checks set again, as at attach: for a setting changed from
      // outside the menu, see menuChecks.
      check: setChecks,
    };
  },
};

const stackSearch = (() => {
  const CALM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // The app's HistorySearch: case and accents fold on both sides, so "ete"
  // finds "été" and "Zurich" finds "Zürich", and every occurrence counts.
  // Folded one code point at a time, keeping where each folded unit came
  // from, so a hit in the folded text maps back to a range of the original.
  const fold = (ch) => ch.normalize('NFD').replace(/\p{M}/gu, '').toLowerCase();
  const folded = (text) => {
    let out = '';
    const starts = [];
    const ends = [];
    let at = 0;
    for (const ch of text) {
      const f = fold(ch);
      for (let k = 0; k < f.length; k++) { starts.push(at); ends.push(at + ch.length); }
      out += f;
      at += ch.length;
    }
    return { text: out, starts: starts, ends: ends };
  };
  // Every place `query` occurs in `text`, as [from, to) of the original. An
  // empty query matches nowhere: an empty field means "show everything", which
  // is the caller's decision, not a match on every box.
  const ranges = (query, text) => {
    const q = folded(query).text;
    if (!q) return [];
    const t = folded(text);
    const hits = [];
    let from = 0;
    for (;;) {
      const i = t.text.indexOf(q, from);
      if (i < 0) break;
      hits.push([t.starts[i], t.ends[i + q.length - 1]]);
      from = i + q.length;
    }
    return hits;
  };
  const matches = (text, query) => !query || ranges(query, text).length > 0;
  // `text` into `el`, with the hits wrapped so they can be lit. A background
  // changes no glyph's advance, so a box measures the same lit or not.
  const write = (el, text, query) => {
    el.textContent = '';
    let at = 0;
    ranges(query, text).forEach((hit) => {
      if (hit[0] > at) appendKeys(el, text.slice(at, hit[0]));
      const lit = document.createElement('span');
      lit.className = 'hist-hit';
      appendKeys(lit, text.slice(hit[0], hit[1]));
      el.append(lit);
      at = hit[1];
    });
    if (at < text.length) appendKeys(el, text.slice(at));
  };

  // The app's SpringValue: one number on a spring, ticked once a frame with
  // the interval the frame actually took, integrated over fixed substeps so
  // it is the same spring at 60 and 120 Hz. The defaults are the search
  // pill's: about a quarter of a second with a small overshoot, quick enough
  // to feel attached to the click, soft enough to read as a spring. A
  // retarget mid-flight keeps its velocity, so an Escape halfway through
  // opening turns round rather than jumping.
  class Spring {
    constructor(value, stiffness, ratio) {
      this.value = value;
      this.target = value;
      this.velocity = 0;
      this.k = stiffness || 700;
      this.c = 2 * (ratio || 0.74) * Math.sqrt(this.k);
      this.frame = 0;
      this.last = 0;
      this.onTick = null;
    }
    snap(value) {
      cancelAnimationFrame(this.frame);
      this.frame = 0;
      this.velocity = 0;
      this.value = value;
      this.target = value;
    }
    animate(target) {
      if (Math.abs(target - this.target) <= 0.5
          && (this.frame || Math.abs(target - this.value) <= 0.5)) return;
      this.target = target;
      if (this.frame) return;
      this.last = 0;
      this.frame = requestAnimationFrame((t) => this.tick(t));
    }
    tick(now) {
      // Clamped: the first tick has no predecessor, and a stall must not be
      // integrated as one enormous step.
      const dt = this.last ? Math.min(Math.max((now - this.last) / 1000, 1 / 240), 1 / 30) : 1 / 120;
      this.last = now;
      let left = dt;
      while (left > 0) {
        const step = Math.min(1 / 480, left);
        this.velocity += (-this.k * (this.value - this.target) - this.c * this.velocity) * step;
        this.value += this.velocity * step;
        left -= step;
      }
      if (Math.abs(this.value - this.target) < 0.3 && Math.abs(this.velocity) < 8) {
        this.snap(this.target);
      } else {
        this.frame = requestAnimationFrame((t) => this.tick(t));
      }
      if (this.onTick) this.onTick(this.value);
    }
  }

  let instances = 0;

  // The pill, put in the stage next to `history`. The demo lays it out and
  // says when the stack is up; this owns the field, the pin and the query.
  //   onPin()          the field took the keyboard: the stack is now held up
  //   onQuery()        the text changed: repaint, narrowed to it, parked
  //   onUnpin(hadQuery) the keyboard went back: the stack answers to ⌥ again
  const attach = (opts) => {
    const history = opts.history;
    const n = ++instances;
    const el = document.createElement('div');
    el.className = 'demo-search';
    // The field's word, in the page's language: the same one the Notes
    // window's search field shows.
    const label = I18N('search.placeholder', 'Search');
    el.innerHTML =
      '<svg class="ds-icon" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" aria-hidden="true">'
      + '<circle cx="10.4" cy="10.4" r="6.8"/><path d="M15.5 15.5 21.4 21.4"/></svg>'
      + '<input class="ds-field" type="text" placeholder="' + label + '" aria-label="' + label + '" tabindex="-1"'
      + ' autocomplete="off" autocorrect="off" autocapitalize="off" spellcheck="false">'
      + '<span class="ds-hint" aria-hidden="true">⌥F</span>'
      + '<button type="button" class="ds-clear" tabindex="-1" aria-label="Clear">'
      + '<svg viewBox="0 0 24 24" aria-hidden="true"><mask id="ds-x' + n + '"><rect width="24" height="24" fill="#fff"/>'
      + '<path d="M8.5 8.5l7 7M15.5 8.5l-7 7" stroke="#000" stroke-width="2.4" stroke-linecap="round"/></mask>'
      + '<circle cx="12" cy="12" r="10" fill="currentColor" mask="url(#ds-x' + n + ')"/></svg></button>'
      // For measuring the closed pill: the placeholder and the hint in their
      // own fonts, laid out but never seen.
      + '<span class="ds-measure" aria-hidden="true">' + label + '</span>'
      + '<span class="ds-measure ds-hint" aria-hidden="true">⌥F</span>';
    history.parentNode.insertBefore(el, history);
    const field = el.querySelector('.ds-field');
    const icon = el.querySelector('.ds-icon');
    const clear = el.querySelector('.ds-clear');
    const measure = el.querySelectorAll('.ds-measure');

    let focused = false;
    // Pinned by a demo's script rather than by a hand in the field: the
    // keyboard is wherever the visitor left it, and stays there.
    let scripted = false;
    let query = '';
    let visible = false;
    let starved = false;
    const expanded = () => focused || query !== '';

    const spring = new Spring(0);
    spring.onTick = (w) => { el.style.width = Math.round(w) + 'px'; };

    const num = (v) => parseFloat(v) || 0;
    const em = () => num(getComputedStyle(history).fontSize) || 16;
    // Closed: exactly the icon, the word and the hint. Open: the app's 220pt
    // or 0.55 of the stack, whichever is wider, never wider than the stack.
    const compactWidth = () => {
      const cs = getComputedStyle(el);
      const gap = num(cs.columnGap);
      // The icon is SVG, which has no offsetWidth.
      return num(cs.paddingLeft) + icon.getBoundingClientRect().width + gap + measure[0].offsetWidth
        + Math.round(em() * 0.133) + gap + measure[1].offsetWidth + num(cs.paddingRight);
    };
    const openWidth = (stackWidth) =>
      Math.min(stackWidth, Math.max(Math.round(em() * 7.33), Math.round(stackWidth * 0.55)));

    // A pill while idle, the full field while in use, and the change between
    // them sprung, so the field is seen to open out of the pill rather than
    // replace it. Only while the stack is up: a stack arriving on screen
    // builds the field at the width it should already have.
    const layout = (stackWidth, animate) => {
      el.classList.toggle('is-open', expanded());
      const width = expanded() ? openWidth(stackWidth) : Math.min(stackWidth, compactWidth());
      if (animate && !CALM) spring.animate(width);
      else { spring.snap(width); spring.onTick(width); }
    };
    const place = (left, above, near) => {
      el.style.left = left;
      if (above) { el.style.top = 'auto'; el.style.bottom = near; }
      else { el.style.bottom = 'auto'; el.style.top = near; }
    };
    const setVisible = (on) => { visible = on; el.classList.toggle('is-visible', on); };
    const setBelow = (on) => el.classList.toggle('is-below', on);
    // Nowhere to put the stack: it leaves the screen, keyboard included, and
    // comes back with it. Not an outside click, so the pin survives it.
    const setStarved = (on) => {
      if (starved === on) return;
      starved = on;
      el.classList.toggle('is-starved', on);
      if (!on && focused && !scripted && document.activeElement !== field) field.focus();
    };
    // The stack opening: the pill is the nearest thing to the live box, so it
    // rises first and the boxes follow it.
    const rise = () => {
      el.classList.remove('is-rising');
      void el.offsetWidth;
      el.classList.add('is-rising');
      el.addEventListener('animationend', () => el.classList.remove('is-rising'), { once: true });
    };

    const setQuery = (text) => {
      query = text;
      el.classList.toggle('has-text', query !== '');
    };
    const changed = () => { setQuery(field.value); opts.onQuery(); };

    // Give the keyboard back and let the stack answer to ⌥ again. The field
    // is emptied whichever way this came. The boxes are left as the search
    // had them: the usual next step is the stack fading out, and what fades
    // should be what was on screen.
    const unpin = () => {
      if (!focused && query === '') return;
      const hadQuery = query !== '';
      focused = false;
      scripted = false;
      field.value = '';
      setQuery('');
      if (document.activeElement === field) field.blur();
      opts.onUnpin(hadQuery);
    };

    field.addEventListener('focus', () => {
      if (focused) return;
      focused = true;
      opts.onPin();
    });
    field.addEventListener('input', changed);
    field.addEventListener('keydown', (e) => {
      if (e.key === 'Escape') { e.preventDefault(); unpin(); return; }
      if (!e.altKey || e.metaKey || e.ctrlKey) return;
      // ⌥ is what raised the stack, so it is still down as the first letters
      // of a search are typed, and ⌥ with a letter is the layout's alternate
      // character: "an" arrives as "åñ". Stripped from anything that would
      // type a character, and left on everything else, so ⌥⌫ and ⌥← still
      // edit the way they do in any field. ⌥F is the hotkey and types nothing.
      let ch = null;
      const letter = /^Key([A-Z])$/.exec(e.code);
      if (letter) ch = e.shiftKey ? letter[1] : letter[1].toLowerCase();
      else if (/^Digit[0-9]$/.test(e.code)) ch = e.code.slice(-1);
      else if (e.code === 'Space') ch = ' ';
      if (!ch) return;
      e.preventDefault();
      if (e.code === 'KeyF') return;
      field.setRangeText(ch, field.selectionStart, field.selectionEnd, 'end');
      changed();
    });
    // The keyboard went elsewhere: a click on the page, another window. Either
    // is an outside click as far as the pin is concerned.
    field.addEventListener('blur', () => { if (focused && !starved) unpin(); });
    // A click on the pill is a click into the field; on the ✕, one that
    // empties it and keeps the keyboard for the next word; on a box in the
    // stack, inside the panel, so the pin stays. mousedown rather than
    // pointerdown, which is the one Safari lets cancel a focus change.
    clear.addEventListener('mousedown', (e) => e.preventDefault());
    clear.addEventListener('click', () => { field.value = ''; changed(); field.focus(); });
    el.addEventListener('mousedown', (e) => {
      if (e.target === field || clear.contains(e.target)) return;
      e.preventDefault();
      field.focus();
    });
    el.addEventListener('click', (e) => {
      if (e.target === field || clear.contains(e.target)) return;
      field.focus();
    });
    history.addEventListener('mousedown', (e) => { if (focused) e.preventDefault(); });
    // ⌥F, only while the stack is up: the rest of the time it belongs to
    // whatever is in front.
    window.addEventListener('keydown', (e) => {
      if (!e.altKey || e.metaKey || e.ctrlKey || e.code !== 'KeyF') return;
      if (!visible || starved) return;
      e.preventDefault();
      if (!focused) field.focus();
    });
    // Another window took the front. The browser would hand the field its
    // focus back on return, and with it the pin, so it is let go for good.
    window.addEventListener('blur', () => {
      unpin();
      setTimeout(() => { if (document.activeElement === field) field.blur(); }, 0);
    });

    return {
      el: el,
      get query() { return query; },
      get pinned() { return focused; },
      matches: (text) => matches(text, query),
      write: (node, text) => write(node, text, query),
      layout: layout,
      place: place,
      setVisible: setVisible,
      setBelow: setBelow,
      setStarved: setStarved,
      height: () => el.offsetHeight,
      rise: rise,
      unpin: unpin,
      // For the demos' own searches, which have no hands: the keyboard into
      // the field, and text into it a piece at a time, as if typed. `open`
      // pins the field without the keyboard: the landing pages search on
      // the page itself, and a page must not take the focus from a visitor
      // who is reading, or typing, somewhere else on it. What it costs is
      // the caret; the recordings' epilogue, which has the page to itself,
      // takes the real focus for it.
      focus: () => field.focus(),
      open: () => { if (focused) return; focused = true; scripted = true; opts.onPin(); },
      type: (text) => { field.value += text; changed(); },
    };
  };

  // The app's originXSpring and originYSpring. The live box hugs its text
  // and grows a line at a time as a sentence wraps, and a stack that jumped
  // the line with it read as a jolt; the box itself stays put, since it
  // changes several times a second and is what is being read, and the stack
  // and its pill follow it on a stiff spring, a tenth of a second behind, no
  // overshoot. Straight there when the stack is arriving, since there is
  // nowhere for it to be coming from. In px of the stage, where the demos
  // used to write percentages: the target is recomputed whenever the box
  // moves, which is what the percentages were for.
  const follow = (history, search) => {
    const x = new Spring(0, 900, 0.9);
    const y = new Spring(0, 900, 0.9);
    let above = true;
    let block = 0;
    const lay = () => {
      const left = Math.round(x.value) + 'px';
      const near = Math.round(y.value);
      history.style.left = left;
      search.place(left, above, near + 'px');
      if (above) { history.style.top = 'auto'; history.style.bottom = (near + block) + 'px'; }
      else { history.style.bottom = 'auto'; history.style.top = (near + block) + 'px'; }
    };
    x.onTick = lay;
    y.onTick = lay;
    // `left` is the live box's centre and `near` the stack's edge nearest it,
    // both from the stage's own edges; `gapBlock` is the pill and the gap
    // past it, where the boxes start.
    return (left, near, isAbove, gapBlock, animate) => {
      above = isAbove;
      block = gapBlock;
      if (animate && !CALM) { x.animate(left); y.animate(near); }
      else { x.snap(left); y.snap(near); }
      lay();
    };
  };

  return { attach: attach, follow: follow };
})();

// Resizing the demo windows by their edges, as on a Mac: the pointer within
// four pixels of an edge, on either side of it, takes hold of that edge, and
// a corner takes hold of two. The hit test runs on the stage rather than on
// the windows, because half of the band is outside the window, over the
// desktop or over whatever window is behind; and it walks the windows front
// to back, so a band under another window's body is not reachable through
// it, exactly as a real desktop has it. Mouse only, like moving them: on a
// phone the edges are inside a page you are trying to scroll.
//
// `front` gives the windows front to back; `onGrab` is what taking hold of a
// window means to the demo, which is bringing it forward. `pin` is shared
// with moving: a window at explicit fractions of the stage, in place of the
// insets it was laid out with and the margin it may have been centred by,
// which would move it by that much the moment it is picked up or pulled.
const windowResize = (() => {
  const SLOP = 4;
  // How much less than the corner radius the corner's grab reaches inward.
  const CORNER_TRIM = 8;
  const pin = (stage, win) => {
    const bounds = stage.getBoundingClientRect();
    const r = win.getBoundingClientRect();
    const box = {
      left: (r.left - bounds.left) / bounds.width,
      top: (r.top - bounds.top) / bounds.height,
      width: r.width / bounds.width,
      height: r.height / bounds.height,
    };
    win.style.inset = 'auto';
    win.style.marginInline = '0';
    win.style.left = (box.left * 100) + '%';
    win.style.top = (box.top * 100) + '%';
    win.style.width = (box.width * 100) + '%';
    win.style.height = (box.height * 100) + '%';
    return box;
  };
  // The floor when a window names none of its own (styles.css, --min-w and
  // --min-h): about a title bar and a few lines, in units of the model, so it
  // is the same window at any screen size.
  const MIN_W_U = 30;
  const MIN_H_U = 20;
  // The steps at which a window shows less, in the same units, each read from
  // the window's own custom property and worn as a class: what a Mac app does
  // when its window is dragged in, decided per app in the stylesheet.
  const STEPS = [['narrow', '--narrow'], ['cramped', '--cramped'], ['short', '--short'], ['squat', '--squat']];
  const units = (win, name, fallback) => {
    const v = parseFloat(getComputedStyle(win).getPropertyValue(name));
    return isNaN(v) ? fallback : v;
  };
  // The window's size in units, against its steps.
  const dress = (win, wU, hU) => {
    STEPS.forEach(([name, prop]) => {
      const at = units(win, prop, NaN);
      win.classList.toggle('is-' + name, (name === 'narrow' || name === 'cramped' ? wU : hU) < at);
    });
  };

  const edgesAt = (front, x, y) => {
    for (const win of front()) {
      const r = win.getBoundingClientRect();
      if (x < r.left - SLOP || x > r.right + SLOP || y < r.top - SLOP || y > r.bottom + SLOP) continue;
      // The corners take a wider hand than the edges. A window's corners are
      // rounded (2.4 units, styles.css), so the point where two edges meet
      // is empty and a band 4px wide misses the arc; the corner's grab runs
      // the radius in from each edge, less a little so the body's own
      // corner stays the body's, as macOS gives a corner more than an edge.
      const arc = (parseFloat(getComputedStyle(win).borderTopLeftRadius) || 0) + SLOP - CORNER_TRIM;
      const nearL = x - r.left <= arc;
      const nearR = r.right - x <= arc;
      const nearT = y - r.top <= arc;
      const nearB = r.bottom - y <= arc;
      const corner = (nearL || nearR) && (nearT || nearB);
      const edges = {
        left: Math.abs(x - r.left) <= SLOP || (corner && nearL),
        right: Math.abs(x - r.right) <= SLOP || (corner && nearR),
        top: Math.abs(y - r.top) <= SLOP || (corner && nearT),
        bottom: Math.abs(y - r.bottom) <= SLOP || (corner && nearB),
      };
      if (edges.left || edges.right || edges.top || edges.bottom) return { win: win, edges: edges };
      // Over this window's body, which covers whatever is under it.
      return null;
    }
    return null;
  };
  const cursorFor = (e) =>
    (e.left && e.top) || (e.right && e.bottom) ? 'nwse'
      : (e.right && e.top) || (e.left && e.bottom) ? 'nesw'
        : e.left || e.right ? 'ew' : 'ns';

  const attach = (opts) => {
    const stage = opts.stage;
    let grab = null;
    // Not the overlay, the stack or the switcher: those are above the windows
    // and have pointers of their own.
    const ignore = (event) =>
      event.pointerType !== 'mouse'
      || !!event.target.closest('.demo-overlay, .demo-history, .demo-search, .demo-switcher');

    const end = () => {
      if (!grab) return;
      if (stage.hasPointerCapture(grab.pointerId)) stage.releasePointerCapture(grab.pointerId);
      grab = null;
      delete stage.dataset.resize;
    };

    // In the capture phase, ahead of the title bar's own pointerdown: the top
    // edge's band lies across the bar, and a press there is a resize.
    stage.addEventListener('pointerdown', (event) => {
      if (event.button !== 0 || ignore(event)) return;
      const hit = edgesAt(opts.front, event.clientX, event.clientY);
      if (!hit) return;
      event.preventDefault();
      event.stopPropagation();
      try { stage.setPointerCapture(event.pointerId); } catch (e) { /* pointer gone */ }
      const bounds = stage.getBoundingClientRect();
      // The model's unit, as the stylesheet sets it on the stage:
      // clamp(4px, 0.8182cqw, 7.2px) of the screen. Computed rather than
      // read, because a custom property comes back from getComputedStyle as
      // the clamp() it was written as, not as a length.
      const screen = stage.closest('.demo-screen') || stage;
      const u = Math.min(7.2, Math.max(4, 0.008182 * screen.getBoundingClientRect().width));
      grab = {
        win: hit.win,
        edges: hit.edges,
        pointerId: event.pointerId,
        box: pin(stage, hit.win),
        x: event.clientX,
        y: event.clientY,
        u: u,
        minW: (units(hit.win, '--min-w', MIN_W_U) * u) / bounds.width,
        minH: (units(hit.win, '--min-h', MIN_H_U) * u) / bounds.height,
      };
      stage.dataset.resize = cursorFor(hit.edges);
      opts.onGrab(hit.win);
    }, true);

    stage.addEventListener('pointermove', (event) => {
      if (!grab) {
        // Hovering: the cursor says what a press here would take hold of.
        const hit = ignore(event) ? null : edgesAt(opts.front, event.clientX, event.clientY);
        if (hit) stage.dataset.resize = cursorFor(hit.edges);
        else delete stage.dataset.resize;
        return;
      }
      const bounds = stage.getBoundingClientRect();
      const dx = (event.clientX - grab.x) / bounds.width;
      const dy = (event.clientY - grab.y) / bounds.height;
      let { left, top, width, height } = grab.box;
      const e = grab.edges;
      if (event.altKey) {
        // ⌥ held, as on a Mac: the window resizes about its centre, the
        // opposite edge moving as far the other way, and from a corner on
        // both axes at once. Read off the event each move, so the key can
        // go down or up mid-drag as it can on the desktop.
        const cx = left + width / 2;
        const cy = top + height / 2;
        if (e.left || e.right) width = Math.max(grab.minW, width + 2 * (e.left ? -dx : dx));
        if (e.top || e.bottom) height = Math.max(grab.minH, height + 2 * (e.top ? -dy : dy));
        // Upwards it stops at the top of the stage, as moving does: the
        // underside of the menu bar; with the centre held, that caps the
        // height at twice the centre's depth.
        height = Math.min(height, 2 * cy);
        left = cx - width / 2;
        top = cy - height / 2;
      } else {
        // An edge moves and the opposite one stays, so a window pulled by its
        // left edge grows leftwards; the floor holds the still edge in place.
        if (e.left) { const w = Math.max(grab.minW, width - dx); left += width - w; width = w; }
        if (e.right) width = Math.max(grab.minW, width + dx);
        if (e.top) {
          let h = Math.max(grab.minH, height - dy);
          let t = top + height - h;
          if (t < 0) { h += t; t = 0; }
          top = t; height = h;
        }
        if (e.bottom) height = Math.max(grab.minH, height + dy);
      }
      grab.win.style.left = (left * 100) + '%';
      grab.win.style.top = (top * 100) + '%';
      grab.win.style.width = (width * 100) + '%';
      grab.win.style.height = (height * 100) + '%';
      dress(grab.win, (width * bounds.width) / grab.u, (height * bounds.height) / grab.u);
    });
    stage.addEventListener('pointerleave', () => { if (!grab) delete stage.dataset.resize; });

    ['pointerup', 'pointercancel', 'lostpointercapture'].forEach((type) =>
      stage.addEventListener(type, end)
    );
  };

  return { attach: attach, pin: pin };
})();

// Writing, in every window that is a document. While such a window is in
// front the caret moves: a notes page or a Word, Docs or Granola document
// grows a line under the last one, the code editor adds tokens to a new line,
// Numbers fills the selected cell and steps down the column. Nothing is
// typed in words, so nothing here needs translating; the skeleton lines grow
// the way the ones already there were drawn. Behind another window a document
// holds still, as it does on a real desktop with the focus elsewhere.
(function liveWriting() {
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const rand = (a, b) => a + Math.random() * (b - a);
  const pick = (list) => list[Math.floor(Math.random() * list.length)];

  // Whether a demo is on screen, so nothing is drawn where nobody can see it.
  const onScreen = new WeakMap();
  const watch = 'IntersectionObserver' in window
    ? new IntersectionObserver((entries) => entries.forEach((e) => onScreen.set(e.target, e.isIntersecting)), { threshold: 0.15 })
    : null;
  const screenOf = (el) => el.closest('.demo-screen');
  const awake = (win) => {
    const screen = screenOf(win);
    if (!screen) return false;
    if (watch && !onScreen.has(screen)) { onScreen.set(screen, true); watch.observe(screen); }
    return win.classList.contains('is-front') && !document.hidden && onScreen.get(screen) !== false;
  };

  // A writer is a function returning the delay before its next step.
  const run = (win, step) => {
    const tick = () => {
      const wait = awake(win) ? step() : 300;
      setTimeout(tick, wait);
    };
    setTimeout(tick, rand(400, 1200));
  };

  // ── documents: a line grows under the caret ──────────────────────────
  document.querySelectorAll('.notes-doc, .lw-doc').forEach((doc) => {
    const caret = doc.querySelector(':scope > .notes-caret');
    const win = doc.closest('.demo-window');
    if (!caret || !win) return;
    // The section being written: the run of lines just above the caret. It
    // may grow by two before the oldest line goes, so the page keeps its height.
    const section = () => {
      const out = [];
      let el = row.previousElementSibling;
      while (el && el.tagName === 'I') { out.unshift(el); el = el.previousElementSibling; }
      return out;
    };
    const row = document.createElement('span');
    row.className = 'lw-write';
    const line = document.createElement('i');
    line.style.width = '0%';
    row.append(line, caret);
    doc.append(row);
    const limit = section().length + 2;
    let width = 0;
    let target = rand(55, 96);
    run(win, () => {
      width = Math.min(target, width + rand(2.5, 6.5));
      line.style.width = width + '%';
      if (width < target) return rand(110, 190);
      // The line is done: it joins the page, and a fresh one starts.
      const done = line.cloneNode();
      row.before(done);
      const lines = section();
      if (lines.length > limit) lines[0].remove();
      width = 0;
      line.style.width = '0%';
      target = Math.random() < 0.15 ? rand(28, 50) : rand(55, 96);
      return rand(350, 700);
    });
  });

  // ── the code editor: tokens land on a new line ───────────────────────
  document.querySelectorAll('.lw-lines').forEach((lines) => {
    const win = lines.closest('.demo-window');
    if (!win) return;
    const limit = lines.children.length;
    const caret = document.createElement('span');
    caret.className = 'notes-caret lw-caret-code';
    let current = null;
    let count = 0;
    let want = 0;
    run(win, () => {
      if (!current) {
        current = document.createElement('span');
        current.className = 'lw-line';
        current.style.paddingLeft = pick([6, 12, 12, 18]) + '%';
        current.append(caret);
        lines.append(current);
        while (lines.children.length > limit) lines.firstElementChild.remove();
        count = 0;
        want = Math.floor(rand(2, 6));
        return rand(200, 400);
      }
      const tok = document.createElement('i');
      tok.className = 'lw-tok-' + pick(['p', 'p', 'p', 'k', 't', 'f', 's', 'n']);
      tok.style.width = rand(3.9, 15.6).toFixed(1) + '%';
      caret.before(tok);
      count++;
      if (count < want) return rand(220, 420);
      // Line finished; a beat, then the next one.
      current = null;
      return rand(450, 900);
    });
  });

  // ── the spreadsheet: the selected cell fills, then the one below ─────
  document.querySelectorAll('.lw-sheet').forEach((sheet) => {
    const win = sheet.closest('.demo-window');
    const label = sheet.querySelector('.lw-formula-bar span');
    const bar = sheet.querySelector('.lw-formula-bar i');
    const cells = [...sheet.querySelectorAll('.lw-cell')];
    const cols = 6;
    if (!win || !cells.length) return;
    let at = cells.findIndex((c) => c.classList.contains('is-sel'));
    if (at === -1) at = 0;
    let fill = cells[at].querySelector('i');
    let width = parseFloat(fill.style.width) || 0;
    let target = width || rand(40, 75);
    let phase = 'fill';
    const name = (i) => 'ABCDEF'[i % cols] + (Math.floor(i / cols) + 1);
    run(win, () => {
      if (phase === 'fill') {
        width = Math.min(target, width + rand(4, 9));
        fill.style.width = width + '%';
        if (bar) bar.style.width = (width * 0.6) + '%';
        if (width < target) return rand(90, 160);
        phase = 'move';
        return rand(400, 800);
      }
      // Return: the selection steps down the column, wrapping at the bottom.
      cells[at].classList.remove('is-sel');
      at = (at + cols) % cells.length;
      cells[at].classList.add('is-sel');
      if (label) label.textContent = name(at);
      fill = cells[at].querySelector('i');
      width = 0;
      fill.style.width = '0%';
      target = rand(40, 75);
      phase = 'fill';
      return rand(200, 350);
    });
  });
})();

(function menuBarClock() {
  const el = document.getElementById('mb-time');
  if (!el) return;

  // macOS shows weekday, date and time in the user's own locale.
  const fmt = new Intl.DateTimeFormat(navigator.language || 'en-GB', {
    weekday: 'short',
    day: 'numeric',
    month: 'short',
    hour: 'numeric',
    minute: '2-digit',
  });

  let timer;
  const tick = () => {
    el.textContent = fmt.format(new Date());
    // Re-arm on the next minute boundary rather than polling every second.
    clearTimeout(timer);
    timer = setTimeout(tick, 60000 - (Date.now() % 60000) + 50);
  };

  tick();
  // A backgrounded tab throttles timers, so resync when it comes back.
  document.addEventListener('visibilitychange', () => {
    if (!document.hidden) tick();
  });
})();

// /podcasts: the same player as the home page, and on that page it is always
// playing — the waveform moves, the clock runs, the played bars fill — because
// nothing there pauses it: the page's point is an episode going on while you
// do something else. The home page's own captionDemo owns its player and its
// pauses, so this stands down where that runs.
(function podcastPlaying() {
  if (document.getElementById('caption-box')) return;
  const win = document.querySelector('.demo-window.win-player');
  const wave = document.getElementById('pod-wave');
  if (!win || !wave) return;
  win.classList.add('is-playing');
  if (window.matchMedia('(prefers-reduced-motion: reduce)').matches) return;
  const fill = document.getElementById('pod-fill');
  const clock = document.getElementById('pod-elapsed');
  const bars = [...wave.children];
  const START = 18 * 60 + 24;   // 18:24, where the markup starts
  const TOTAL = 41 * 60 + 7;    // 41:07
  const RATE = 4;               // seconds of episode per second of demo
  let at = START;
  const mmss = (s) => Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');
  const paint = () => {
    const pct = at / TOTAL;
    if (fill) fill.style.width = (pct * 100).toFixed(2) + '%';
    if (clock) clock.textContent = mmss(at);
    const played = Math.round(pct * bars.length);
    bars.forEach((b, i) => b.classList.toggle('is-played', i < played));
  };
  paint();
  setInterval(() => {
    if (document.hidden) return;
    // Round and round: the episode starts over rather than ending.
    at = at + RATE > TOTAL ? START : at + RATE;
    paint();
  }, 1000);
})();

(function captionDemo() {
  const box = document.getElementById('caption-box');
  const out = document.getElementById('caption-text');
  const live = document.getElementById('caption-live');
  const glyph = document.getElementById('mb-glyph');
  const switcher = document.getElementById('switcher');
  const windows = document.querySelectorAll('.demo-window');
  if (!box || !out) return;
  const demoEl = box.closest('.demo');
  const screen = document.querySelector('.demo-screen');
  // The settings, see SETTINGS: the app's defaults, under the page's seed.
  const S = seedDemo(screen, {});
  ringFor(box);
  // The glow along the box's bottom edge, on a mock voice while words land.
  const glow = borealis.attach(box);
  if (glow) glow.apply(S);

  // Named as the Mac names them in its menu bar: Zoom's process is zoom.us.
  const APPS = {
    meeting: I18N('app.meeting', 'zoom.us'),
    notes: I18N('app.notes', 'Notes'),
    player: I18N('app.player', 'Spotify'),
  };

  // Every icon carries its own name, and only the selected one shows it. That is
  // what makes the label move with the selection, and it is why the panel's
  // width is the icons' business alone: the label is out of flow, so a long app
  // name cannot stretch the thing it is labelling.
  windows.length && switcher.querySelectorAll('.sw-app').forEach((el) => {
    const label = el.querySelector('.sw-name');
    if (label) label.textContent = APPS[el.dataset.app];
  });

  // The transport runs only while the player is the window in front, and runs
  // faster than real time on purpose: a scene lasts about a dozen seconds, and a
  // real playhead would not visibly move in that. The clock counting up is the
  // part people read as "this is playing", so that is the part that has to move.
  const CALM = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  // Who is talking, handed round the tiles the way it goes in a real call:
  // never straight back to the same person, and held for an uneven beat,
  // because a fixed rotation reads as a carousel rather than a conversation.
  const speakers = (() => {
    const tiles = [...document.querySelectorAll('.win-meeting .tile')];
    let timer = null;
    let at = 0;
    const hand = (to) => {
      at = to;
      tiles.forEach((t, i) => t.classList.toggle('is-speaking', i === at));
    };
    const step = () => {
      hand((at + 1 + Math.floor(Math.random() * (tiles.length - 1))) % tiles.length);
      timer = setTimeout(step, 2100 + Math.random() * 1700);
    };
    let running = false;
    return (on) => {
      // Only on the change. This is called on every switch now, not just when
      // the call fronts, and re-running it while the call was already talking
      // handed the ring back to the first tile each time.
      if (on === running) return;
      running = on;
      clearTimeout(timer);
      // Stopping used to mean stopping the hand-off and nothing else, which left
      // whoever was talking wearing the ring. On a stack that did not matter,
      // because the call was behind one window and barely visible; fanned out it
      // is a third of the screen, and a ring pulsing away under the podcast said
      // a meeting was live in a scene about a podcast. Put the tiles back to
      // nobody speaking, and the window goes quiet with the scene.
      if (!on || !tiles.length) {
        tiles.forEach((t) => t.classList.remove('is-speaking'));
        return;
      }
      // Somebody is talking the moment the call is in front. Reduced motion gets
      // that as a still ring: it is who is speaking, not an animation.
      hand(0);
      if (CALM) return;
      timer = setTimeout(step, 1900);
    };
  })();

  const playhead = (() => {
    const fill = document.getElementById('pod-fill');
    const clock = document.getElementById('pod-elapsed');
    const bars = [...document.querySelectorAll('#pod-wave i')];
    const START = 18 * 60 + 24;   // 18:24, where the markup starts
    const TOTAL = 41 * 60 + 7;    // 41:07
    const RATE = 4;               // seconds of episode per second of demo
    let timer = null;
    let at = START;

    const mmss = (s) =>
      Math.floor(s / 60) + ':' + String(Math.floor(s % 60)).padStart(2, '0');

    const paint = () => {
      const pct = at / TOTAL;
      if (fill) fill.style.width = (pct * 100).toFixed(2) + '%';
      if (clock) clock.textContent = mmss(at);
      const played = Math.round(pct * bars.length);
      bars.forEach((b, i) => b.classList.toggle('is-played', i < played));
    };

    let running = false;
    return (on) => {
      if (!bars.length || CALM) return;
      // Only on the change, for the same reason as the speakers above: the
      // episode now runs on behind the notes, and restarting it every time
      // something else fronted pinned the clock to 18:24.
      if (on === running) return;
      running = on;
      clearInterval(timer);
      if (!on) return;
      at = START;   // every time it starts playing again, it starts here
      paint();
      timer = setInterval(() => {
        // A backgrounded tab should not run the episode on without anybody
        // watching, or coming back to it shows a clock that has raced ahead.
        if (document.hidden) return;
        at = Math.min(TOTAL, at + RATE);
        paint();
      }, 1000);
    };
  })();

  // Which window is actually in front, updated the moment it fronts rather than
  // once a switch has finished: a switch interrupted by a second click has
  // already fronted its window, and a loop carrying that in a local of its own
  // would open the next ⌘-tab panel on the wrong app.
  let frontApp = 'meeting';

  // Back to front, and the only thing that decides what covers what. The three
  // windows used to share one z-index with the front one lifted above them, so
  // everything behind fell back on the order it happens to sit in the markup:
  // raising the notes also carried the podcast over the call, because the
  // podcast is written last. A desktop does not work that way. Whatever you
  // raise goes on top and the rest keep the order they were already in, so the
  // stack is a record of what you have looked at, however you got there: the
  // scene loop, the buttons under it, a click on a window, or a drag by its
  // title bar all arrive here.
  const stack = ['notes', 'player', 'meeting'];
  // Two of the three windows make a sound, and the one higher in the stack is
  // the one making it: switching between them hands the sound over rather than
  // stopping it, and the notes never take it, so something is always playing.
  const playingApp = () =>
    stack.indexOf('meeting') > stack.indexOf('player') ? 'meeting' : 'player';

  const restack = (app) => {
    const at = stack.indexOf(app);
    if (at !== -1) stack.splice(at, 1);
    stack.push(app);
    const playing = playingApp();
    windows.forEach((w) => {
      // 1 to 3, well under the switcher at 6 and the caption at 10, both of
      // which are above every window by definition.
      w.style.setProperty('--z', stack.indexOf(w.dataset.app) + 1);
      w.classList.toggle('is-playing', w.dataset.app === playing);
    });
  };

  const mbApp = document.getElementById('mb-app');
  const APP_NAMES = { meeting: 'zoom.us', notes: 'Notes', player: 'Spotify' };
  const front = (app) => {
    frontApp = app;
    restack(app);
    // The menu bar names the app in front, as the real one does, with the
    // same name the switcher shows for it.
    if (mbApp) mbApp.textContent = I18N('app.' + app, APP_NAMES[app]);
    windows.forEach((w) => w.classList.toggle('is-front', w.dataset.app === app));
    // Both on the same rule as the class above, and neither on being in front:
    // fronting the notes leaves whichever was playing still playing behind them.
    playhead(playingApp() === 'player');
    speakers(playingApp() === 'meeting');
  };
  const select = (app) => {
    switcher.querySelectorAll('.sw-app').forEach((el) =>
      el.classList.toggle('is-selected', el.dataset.app === app)
    );
  };

  // Which app the box names: the one making the sound, see playingApp, the
  // way the app reads it off what Core Audio reports playing. The call's and
  // the player's windows carry data-audio, naming their icon in
  // assets/apps/dock/; the notes never do, so fronting them leaves the call's
  // name on the box, and fronting the player hands it over.
  const sourceOf = (app) => {
    const w = [...windows].find((x) => x.dataset.app === app);
    return w && w.dataset.audio
      ? { icon: w.dataset.audio, name: I18N('app.' + app, APP_NAMES[app]) }
      : null;
  };
  // Listen To → the microphone, from the demo's menu: the box wears MIC and
  // keeps it whatever window is playing, until All system audio is picked
  // again and the row follows the sound as before. The stack's boxes keep
  // the source each closed under, as the app's do. The menu bar shows the
  // orange pill macOS puts up while something listens (.mb-mic). From the
  // seed first — the app's welcome window hands over what it is listening
  // to with the rest of its settings — and the app's changes follow
  // through applySettings, as the box's look does.
  let micOn = !!S.microphone;
  const micPill = demoEl && demoEl.querySelector('.mb-mic');
  if (micPill) micPill.classList.toggle('is-on', micOn);
  const playing = () => (micOn ? MIC : sourceOf(playingApp()));

  // Three scenes: the call, whatever you switch to while it keeps playing, and
  // the podcast. The captions are what the audio is saying.
  const SCENES = [
    {
      app: 'meeting',
      lines: [
        I18N('line.meeting1', 'Universal subtitles for any app, live on your Mac.'),
        I18N('line.meeting2', 'In a meeting, second language or not, one missed word costs you the next three.'),
        I18N('line.meeting3', 'So the captions run live, over the call, while people are talking.'),
      ],
    },
    {
      app: 'notes',
      lines: [
        I18N('line.notes1', 'Switch to your notes and the meeting carries on without you actively watching it.'),
        I18N('line.notes2', 'The overlay stays above every window, so you keep the thread.'),
      ],
    },
    {
      app: 'player',
      lines: [
        I18N('line.player1', 'The same for a podcast, a lecture, or a video.'),
        I18N('line.player2', 'And none of it leaves the Mac: it runs on the Neural Engine, on-device. Fully local and private.'),
      ],
    },
  ];

  // An epilogue for the recordings, off on the site: the stack and its search,
  // narrated. The capture sets window.SUBTITLES_EPILOGUE and two lines are
  // said before the podcast's last: the stack rises as ⌥ is said in the first,
  // the field opens and a word goes in as ⌥F is said in the second, and both
  // are let go under "none of it leaves the Mac", which then closes the loop
  // as it always did. Without it the loop is the three scenes it always was;
  // the scene bar has no fourth segment and ⌥ is the reader's.
  //
  // `true` takes the lines from the page, translated with the rest of the
  // demo's, and with them the word typed into the search: one the stack holds
  // twice by then, in the call's second line and the notes' first, in that
  // language. An array of two lines is the older contract and keeps its
  // English word.
  const EPILOGUE = Array.isArray(window.SUBTITLES_EPILOGUE) && window.SUBTITLES_EPILOGUE.length === 2
    ? window.SUBTITLES_EPILOGUE.map(String)
    : window.SUBTITLES_EPILOGUE === true
      ? [
        I18N('line.epilogue1', 'Missed a line? Hold ⌥ to rewind: every caption that closed stacks back up.'),
        I18N('line.epilogue2', 'Press ⌥F and type: the stack narrows to the boxes that match.'),
      ]
      : null;
  const EPILOGUE_QUERY = window.SUBTITLES_EPILOGUE === true ? I18N('epilogue.query', 'meeting') : 'meeting';
  // Translation, between the podcast's two lines, on the site as well as on
  // film, as the translation pages show it: a first sentence in another
  // language, shown as it was said; the status menu opening and picking
  // Translate To and this page's language; a second sentence in that other
  // language, shown in this one, with ⌃ giving back what was said. Then the
  // menu again, for Show Both Languages under the same Translate To, and a
  // third sentence that says so, its original under it — and the podcast's
  // last line, which follows, is said in the other language too and shown
  // the same way. The other language is Spanish on the English page and
  // English everywhere else, so what the visitor hears turn into their own
  // is the one they most often have to follow, and it is the one other
  // language from the first of these lines to the last.
  const TRANSLATE = {
    first: I18N('line.translate1', '¿Y cuando es en otro idioma?'),
    source: I18N('line.translate2-src', 'La traducción se hace en tiempo real para ti: pulsa ⌃ para ver el original.'),
    shown: I18N('line.translate2', 'The translation runs live for you: press ⌃ to reveal the original.'),
    bothSource: I18N('line.translate3-src', 'O muestra los dos a la vez: el original se queda debajo de la traducción.'),
    both: I18N('line.translate3', 'Or show both at once: the original stays under the translation.'),
    lastSource: I18N('line.player2-src', 'Y nada de eso sale del Mac: se ejecuta en el Neural Engine, en el dispositivo. Totalmente local y privado.'),
  };
  const LANG = (document.documentElement.lang || 'en').slice(0, 2).toLowerCase();

  front(SCENES[0].app);
  wearApp(box, playing());
  select(SCENES[0].app);
  if (glyph) glyph.classList.add('is-live');

  if (CALM) {
    // No loop to unwind — the scene is just what is on screen, so the bar places
    // it directly. The buttons are still worth having: they are the only way
    // through the three scenes when nothing is animating.
    setKeys(out, SCENES[0].lines[0]);
    box.classList.add('is-visible');
    [...document.querySelectorAll('.demo-scenes .scene-button')].forEach(
      (button, index) =>
        button.addEventListener('click', () => {
          front(SCENES[index].app);
          wearApp(box, playing());
          setKeys(out, SCENES[index].lines[0]);
          document
            .querySelectorAll('.demo-scenes .scene-button')
            .forEach((b, i) =>
              b.setAttribute('aria-current', i === index ? 'true' : 'false')
            );
        })
    );
    return;
  }

  const WORD_MS = 130;   // roughly conversational pace
  const START_MS = 1200; // the page up, and nothing said yet, before the first caption
  const JITTER = 80;
  const GAP_MS = 500;    // blank between boxes
  const FADE_MS = 400;   // .demo-overlay's opacity transition, in styles.css
  // A finished box holds long enough to actually be read: a base beat plus
  // time per word, so a long caption is not gone before you reach the end.
  const holdFor = (words) => Math.min(1500 + words * 130, 4200);

  // One loop for the lifetime of the page. It parks on `paused` instead of
  // returning, because restarting it on every scroll-back stacked a second
  // copy on top of the first and the two raced the caption text.
  let onScreen = true;
  let paused = false;
  const sync = () => { paused = !onScreen || document.hidden; };

  // Set by a click on a scene button or on one of the windows; the loop unwinds
  // at its next beat and picks that scene up from the top. `direct` is the
  // difference between the two: the buttons are a request to go somewhere, and
  // watching the ⌘-tab get there is the point of them, while clicking a window
  // is reaching for that window — the machinery in between would be in the way.
  let jump = null;
  const JUMPED = Symbol('jumped');

  // Every wait currently in flight, so a click can end them all now rather than
  // when their timer says so. Without it a click landed whenever the current
  // wait happened to end, and a caption that has finished typing holds for up to
  // 4.2 seconds — long enough to read as nothing having happened.
  const waking = new Set();
  const wait = (ms) => new Promise((resolve) => {
    const finish = () => { clearTimeout(timer); waking.delete(finish); resolve(); };
    const timer = setTimeout(finish, ms);
    waking.add(finish);
  });
  const wake = () => { [...waking].forEach((finish) => finish()); };

  async function step(ms) {
    await wait(ms);
    while (paused && !jump) await wait(150);
    if (jump) throw JUMPED;
  }

  // One subtitle box: types out, holds long enough to read, clears. The app
  // pages the same way, and shows the newest word dim until it commits.
  //
  // `from` and `to` are the slice of the scene's bar this caption is worth. The
  // bar is walked across it in two moves — one for the typing, one for the hold
  // — because those are the only two moments the loop knows how long the next
  // stretch will take. The second starts from wherever the first actually got
  // to, so the jitter in the typing corrects itself rather than piling up.
  // `source` is what was actually said when `line` is its translation. While
  // the line is up, typing or held, ⌃ swaps the box to the source and back,
  // as it does in the app and on the translation pages, since the line says
  // it will: `cur` is the pair and the word reached, and drawLive draws it
  // in whichever language the key asks for. ⌃ swaps in a sentence that is
  // not the same length as the one being drawn, so progress carries across
  // as a fraction of the line rather than a word index, and the source keeps
  // arriving word by word instead of landing in one block. On the site the
  // key is the visitor's to try; on film, where there is no hand, `ctrlBeat`
  // presses it for a moment in the middle of the hold.
  //
  // With Show Both Languages on, the source goes under the translation as
  // well, as the app's SubtitleView.secondary: the words the caption was
  // made from, as far as the caption has got, at the same fraction of the
  // line that ⌃ draws the source at. Only while the box holds a
  // translation, since in the source language there is nothing to pair it
  // with — the demo passes a source only with Translate To on. And ⌃ then
  // does nothing, in the box or in the stack: the original is already on
  // screen, and there is nothing to reveal.
  let cur = null;
  let ctrlKey = false;
  let ctrlBeat = false;
  const peeking = () => (ctrlKey || ctrlBeat) && !S.bothLanguages;
  const underLive = () => {
    if (!cur || !cur.source || !S.bothLanguages) return '';
    const of = cur.line.split(' ').length;
    return pageOf(cur.source, cur.from, cur.i < 0 ? of : cur.i + 1, of);
  };
  const drawLive = () => {
    if (!cur) return;
    const text = peeking() && cur.source ? cur.source : cur.line;
    const words = text.split(' ');
    // The page's first word and the word reached: the line's own, or the
    // source's, taken as fractions of the line, see above.
    let from = cur.from;
    let i = cur.i;
    if (text !== cur.line) {
      const of = cur.line.split(' ').length;
      const at = (k) => Math.min(Math.round((k / of) * words.length), words.length - 1);
      from = at(from);
      if (i >= 0) i = Math.max(at(i), from);
    }
    if (i < 0) {
      setKeys(out, words.slice(from).join(' '));
      live.textContent = '';
    } else {
      setKeys(out, i > from ? words.slice(from, i).join(' ') + ' ' : '');
      setKeys(live, words[i]);
    }
    setUnder(box, underLive());
  };
  // ⌃ swaps the stack's boxes too, in place, as the app's isSwappingLanguage
  // does: each box keeps both languages from when it closed, and the search
  // reads whichever is showing. A box that closed with nothing said in
  // another language has only the one.
  //
  // With Show Both Languages on, the source goes under each box's text, as
  // the app's stack draws it, and ⌃ swaps nothing, see `peeking`. The
  // pairing is the box's whether or not the setting is on, as the app's
  // stack keeps it, so a box closed with it off shows both once it goes on.
  // The search reads either paragraph, and lights the text's, as the app's
  // does.
  const lineText = (page) => (peeking() && page.source ? page.source : page.text);
  const underText = (page) => (S.bothLanguages && page.source ? page.source : '');
  const pageMatches = (page) => {
    const under = underText(page);
    return search.matches(lineText(page)) || (!!under && search.matches(under));
  };
  const dressLine = (el, page) => {
    search.write(textOf(el), lineText(page));
    setUnder(el, underText(page));
    el.classList.toggle('is-hidden', !pageMatches(page));
  };
  const retextHistory = () => {
    if (!history) return;
    [...history.children].forEach((el) => {
      const page = past.find((p) => String(p.id) === el.dataset.pid);
      if (page) dressLine(el, page);
    });
  };
  const redraw = () => { drawLive(); retextHistory(); };
  window.addEventListener('keydown', (e) => { if (e.key === 'Control') { ctrlKey = true; redraw(); } });
  window.addEventListener('keyup', (e) => { if (e.key === 'Control') { ctrlKey = false; redraw(); } });
  window.addEventListener('blur', () => { ctrlKey = false; redraw(); });

  // `wears` is the app the line belongs to, when the scene knows better than
  // the stack: the podcast's first line starts while its ⌘-tab is still
  // landing, and its words are the podcast's, not the call's still playing
  // under it. Without it the box wears whatever is making the sound. The
  // microphone, when it is listened to, over either: see `boxApp`.
  const boxApp = () => (micOn ? MIC : ((cur && cur.wears) || playing()));
  const setMic = (on) => {
    if (micOn === on) return;
    micOn = on;
    if (micPill) micPill.classList.toggle('is-on', on);
    // The live box changes its row at once, as the app's does when the
    // source changes; a page it closes from here on wears the new one.
    wearApp(box, boxApp());
    queueHole();
  };
  async function say(line, from, to, source, wears) {
    const words = line.split(' ');
    const hold = holdFor(words.length);
    const typing = words.length * (WORD_MS + JITTER / 2);
    const typed = from + (to - from) * (typing / (typing + hold + GAP_MS));

    // The box wears the app its words arrive under, and keeps it when it
    // closes into the stack, whatever is playing by then.
    // The first word of the page on screen: the line's, until the pager
    // below turns the page. `closing` is the source the whole page closes
    // under, read while the line is still the live one.
    let page = 0;
    let closing = null;
    cur = { line: line, source: source || null, i: 0, from: 0, wears: wears || null };
    wearApp(box, boxApp());
    drawLive();
    box.classList.add('is-visible');
    progress(typed, typing);

    try {
      for (let i = 0; i < words.length; i++) {
        if (jump) throw JUMPED;
        cur.i = i;
        drawLive();
        // The app's pager, under a seeded maxLines: a word that takes the
        // box past its lines closes the page before it into the stack and
        // starts the next from that word. Measured with the word in the
        // page and before the frame is painted, so nothing is seen to
        // overflow; the box holds its whole sentence otherwise.
        if (i > page && paged() && overflows(box, S.maxLines)) {
          closePage(pageOf(line, page, i, words.length), boxApp(),
            source && pageOf(source, page, i, words.length));
          page = i;
          cur.from = i;
          drawLive();
        }
        spoke();
        // A comma or full stop gets a beat, the way speech does.
        const punctuated = /[,.;:—]$/.test(words[i]);
        await step(WORD_MS + Math.random() * JITTER + (punctuated ? 180 : 0));
      }

      // Everything commits once the utterance ends.
      cur.i = -1;
      drawLive();
      progress(to, hold + GAP_MS);

      // On film, only under the line that says to press it: the lines with
      // both languages on screen have their original under them already.
      if (source && CAPTURE && /⌃/.test(line)) {
        await step(hold * 0.45);
        ctrlBeat = true;
        redraw();
        await step(1400);
        ctrlBeat = false;
        redraw();
        await step(hold * 0.55);
      } else {
        await step(hold);
      }
      closing = boxApp();
    } finally {
      cur = null;
      ctrlBeat = false;
    }
    box.classList.remove('is-visible');
    // The page has closed. The app records it here too, at the fade, because
    // fading is precisely when somebody looked away and will want it back.
    closePage(page ? pageOf(line, page, words.length, words.length) : line, closing,
      page && source ? pageOf(source, page, words.length, words.length) : source);
    await step(GAP_MS);
  }

  // ⌘-tab: panel up on the current app, selection moves, window fronts as the
  // panel drops — which is when you'd release the key.
  async function switchTo(to) {
    select(frontApp);
    switcher.classList.add('is-visible');
    await step(340);
    select(to);
    await step(560);
    front(to);
    switcher.classList.remove('is-visible');
    await step(220);
  }

  // Both halves of a concurrent pair have to finish before the loop moves on,
  // including when one of them threw: awaiting Promise.all would leave the other
  // running against a loop that has already unwound, and its rejection
  // unhandled a beat later.
  async function both(a, b) {
    const settled = await Promise.allSettled([a, b]);
    const failed = settled.find((result) => result.status === 'rejected');
    if (failed) throw failed.reason;
  }

  // The recordings' epilogue, see EPILOGUE above. Each move lands as the word
  // for it is said, which is what makes it read as the narration doing it: the
  // stack rises as ⌥ comes up in the first line, the field opens as ⌥F does in
  // the second, and a word the stack holds twice by then, in the call's second
  // line and the notes' first, goes in a letter at a time, so the search is
  // seen to narrow seven boxes to two. The scene bar holds where the podcast's
  // first line left it: the epilogue has no segment of its own.
  // ⌥ goes first: unpinning while it still counted as held would repaint the
  // stack with every box back, and that is what would fade. Let go of both
  // at once and what fades is what the search had on screen.
  const endEpilogue = () => {
    if (!search) return;
    altKey = false;
    search.unpin();
    showHistory();
  };

  // The app's status menu, drawn on the page for the recordings only, and
  // walked as the translation pages walk it: the panel opens, Translate To
  // lights, the submenu hangs off it, the language lights, blinks as macOS
  // blinks the item it is about to act on, and takes the check. No pointer
  // is drawn; the highlight moving is the hand.
  const menu = demoEl && demoEl.querySelector('.mn-root');
  const submenu = menu && menu.querySelector('.mn-sub[data-for="translate"]');
  // By hand too, see statusMenu: the rows with a Try badge act on this
  // demo's box and stack, through applySettings below, as the app's own
  // changes do.
  const menuUI = menu && statusMenu.attach({
    root: menu,
    glyph: glyph,
    badge: I18N('menu.demo', 'Try'),
    ...menuChecks(S),
    // Listen To: the call and the player, whichever is playing marked so.
    audio: () => [...windows].filter((w) => w.dataset.audio).map((w) =>
      ({ name: I18N('app.' + w.dataset.app, APP_NAMES[w.dataset.app]), playing: w.dataset.app === playingApp() })),
    watch: [...windows],
    actions: {
      size: (pt) => applySettings({ fontSize: pt }),
      align: (how) => applySettings({ textAlignment: how }),
      icon: (style) => applySettings({ iconStyle: { tab: 'nameTab', off: 'off' }[style] || 'header' }),
      reveal: (on) => applySettings({ revealEnabled: on }),
      history: (on) => applySettings({ historyEnabled: on }),
      both: (on) => applySettings({ bothLanguages: on }),
      listen: (which) => applySettings({ microphone: which === 'mic' }),
      borealis: (look) => applySettings({ borealis: look }),
      glow: (strength) => applySettings({ borealisStrength: strength }),
      theme: (which) => applySettings({ theme: which }),
      reset: () => {
        box.style.left = '';
        box.style.top = '';
        box.style.bottom = '';
        box.style.transform = '';
        queueHole();
      },
    },
  });
  const closeMenu = () => { if (menuUI) menuUI.closeScripted(); };
  // A change to the settings, in place: the keys given, read as the seed
  // is, written over S, and the demo dressed to them again — the box and
  // the stack, the reveal, the stack's depth and expiry, the menu's checks.
  // What is not given stays: the app changing its blur does not undo a size
  // the visitor picked from the menu here, since both write the same S and
  // each writes only what it changed. The menu's rows come through here,
  // and so does the app while its welcome window shows this demo: its
  // Welcome.swift dispatches `subtitles:settings` on the document with the
  // keys that changed, and only those.
  //
  // Show Both Languages is the one setting the loop itself changes: on for
  // the translated lines, and back at the wrap. Back to what the reader has
  // it set to — the seed's value, then the app's or the menu's — not to
  // off, so an app that shows both languages sees its demo do the same
  // through every turn. `bothBase` is that; the loop's own changes say so
  // (`story`) and leave it alone.
  let bothBase = !!S.bothLanguages;
  const applySettings = (given, story) => {
    const changed = readSettings(given);
    if (!Object.keys(changed).length) return;
    Object.assign(S, changed);
    if ('bothLanguages' in changed && !story) bothBase = S.bothLanguages;
    dressDemo(screen, S);
    if (menuUI) menuUI.check(menuChecks(S));
    if ('revealEnabled' in changed) hole.enable(S.revealEnabled);
    if ('historyEnabled' in changed) { historyOn = S.historyEnabled; showHistory(); }
    if ('microphone' in changed) setMic(S.microphone);
    if (('borealis' in changed || 'borealisStrength' in changed) && glow) glow.apply(S);
    // Show Both Languages: the live box and the stack drawn again, the
    // other language under every box that has one, or gone from under it.
    // The stack is repainted whole, since each box's height changes with it.
    if ('bothLanguages' in changed) {
      drawLive();
      if (history && history.classList.contains('is-visible')) paintHistory();
      else retextHistory();
    }
    // A shallower stack loses its oldest boxes now, not at the next close.
    if ('historyDepth' in changed && past.length > pastMax()) {
      past.splice(0, past.length - pastMax());
      if (history && history.classList.contains('is-visible')) paintHistory();
    }
    // The expiry re-armed from the last word, on the new terms.
    if ('historyExpires' in changed || 'historyExpiry' in changed) forget();
    queueHole();
  };
  document.addEventListener('subtitles:settings', (e) => applySettings(e.detail));
  const setTranslation = (target) => {
    if (!submenu) return;
    // The languages are a choice; Show Both Languages, in the submenu with
    // them, is a toggle with its own check, kept — and greyed with
    // translation off, as Translation Timing is, since it does nothing on
    // its own.
    submenu.querySelectorAll('.mn-row').forEach((r) => {
      if (r.dataset.id === 'both') r.classList.toggle('is-dim', target === 'off');
      else r.classList.toggle('is-on', r.dataset.id === target);
    });
    const timing = menu.querySelector('[data-id="timing"]');
    if (timing) timing.classList.toggle('is-dim', target === 'off');
  };
  // The menu walked into Translate To and a row of it taken: the row
  // lights, blinks as macOS blinks the item it is about to act on, and
  // `act` does what the row does. The visitor took the menu down mid-walk:
  // the switch still happens.
  async function walkTranslateTo(id, act) {
    const entry = menu && menu.querySelector('[data-id="translate"]');
    const row = submenu && submenu.querySelector('[data-id="' + id + '"]');
    if (!entry || !row || !menuUI) return;
    const walk = menuUI.walk();
    const cut = () => { act(); walk.end(); };
    walk.hot(entry);
    await step(500);
    if (walk.cancelled) return cut();
    walk.sub(entry);
    await step(450);
    if (walk.cancelled) return cut();
    walk.hot(row);
    await step(650);
    if (walk.cancelled) return cut();
    for (let k = 0; k < 2; k++) {
      walk.cool(row);
      await step(70);
      walk.hot(row);
      await step(70);
    }
    act();
    walk.end();
    await step(350);
  }
  const pickTranslation = (target) => walkTranslateTo(target, () => setTranslation(target));
  // Show Both Languages, set on rather than toggled: a visitor who ticked
  // it first is not unticked by the walk. The loop's own change, so the
  // reader's setting stands behind it (see applySettings).
  const pickBothLanguages = () => walkTranslateTo('both', () => applySettings({ bothLanguages: true }, true));
  // Translation off again, as a turn of the loop starts, and Show Both
  // Languages back to the reader's own setting: set outright, no walk, the
  // way the loop has always let Translate To go at the wrap.
  const dropTranslation = () => {
    setTranslation('off');
    if (S.bothLanguages !== bothBase) applySettings({ bothLanguages: bothBase }, true);
  };
  // Resolves once `text` has been typed into the live box, tentative word
  // included, so a move can land on the word that names it.
  const saidYet = async (text) => {
    while (!(out.textContent + live.textContent).includes(text)) await step(30);
  };
  // Between the podcast's two lines. The stack and its search only on film,
  // with the bar holding where the first line left it; translation on the
  // site as well, taking the first half of what the bar had left for the last
  // line, which then takes the rest. Returns where the bar got to.
  async function epilogue(from, to) {
    if (EPILOGUE && search) {
      await both(say(EPILOGUE[0], from, from), (async () => {
        await saidYet('⌥');
        altKey = true;
        showHistory();
      })());
      await both(say(EPILOGUE[1], from, from), (async () => {
        await saidYet('⌥F');
        search.focus();
        await step(600);
        for (const ch of EPILOGUE_QUERY) { search.type(ch); await step(150); }
      })());
      // Let go: the field empties and the stack fades under the line that
      // follows.
      endEpilogue();
    }
    if (!menu) return from;
    // Somebody speaks the other language and the box shows it as said;
    // Translate To goes on; the next sentence arrives in this page's
    // language, and ⌃ shows for a beat what was actually said. Show Both
    // Languages goes on, and the next sentence says so, its original under
    // it. Three lines in the bar's first half, a sixth each; the podcast's
    // last line takes the rest.
    const sixth = (to - from) / 6;
    await say(TRANSLATE.first, from, from + sixth);
    await pickTranslation(LANG);
    await say(TRANSLATE.shown, from + sixth, from + sixth * 2, TRANSLATE.source);
    // Already on, from the reader's own setting: nothing to walk to.
    if (!S.bothLanguages) await pickBothLanguages();
    await say(TRANSLATE.both, from + sixth * 2, from + sixth * 3, TRANSLATE.bothSource);
    return from + sixth * 3;
  }

  async function loop() {
    let index = 0;
    // Set by a jump, cleared by the scene that answers it: the switch that gets
    // there runs on its own rather than under the first caption.
    let picked = false;
    // Set by a jump that found a caption up: that caption fades out whole
    // before the next turn does anything, rather than being wiped mid-fade.
    let fading = false;

    for (;;) {
      const scene = SCENES[index];
      const slice = 1 / scene.lines.length;
      // The scene's own app when it makes a sound, for the boxes to wear;
      // the notes make none, and their lines are the call's.
      const wears = sourceOf(scene.app);
      const deliberate = picked;
      picked = false;

      paintScene(index);
      // Back to empty before the first caption of the scene, and instantly: the
      // wrap-around switch runs before any caption does, and the bar would
      // otherwise sit full through it.
      progress(0, 0);

      try {
        if (fading) {
          fading = false;
          await step(FADE_MS);
        }
        // Against what is actually in front, not against what the last switch
        // meant to leave there: an interrupted one may have fronted its window
        // already, and this scene's may be it.
        if (scene.app !== frontApp && (index === 0 || deliberate)) {
          // Coming back round to the top, or somebody picked this scene. The
          // switch runs on its own, with the captions starting after it lands,
          // so the loop reads as beginning again rather than as a first line
          // that started while the previous scene's window was still in front.
          // Every other switch stays concurrent, below, because that is the
          // point being made.
          await switchTo(scene.app);
        }
        // The top of the loop, its switch landed and nothing said yet: where
        // tools/make-video.py cuts a recording, one turn from here to here.
        if (index === 0) demoEl.dispatchEvent(new CustomEvent('subtitles:loop', { bubbles: true }));
        if (scene.app !== frontApp) {
          // Deliberately concurrent: the caption keeps running straight
          // through the app switch, which is the whole point being made.
          await both(say(scene.lines[0], 0, slice, null, wears), switchTo(scene.app));
        } else {
          await say(scene.lines[0], 0, slice, null, wears);
        }

        for (let j = 1; j < scene.lines.length; j++) {
          // Before the last line of the last scene, so that line closes the
          // loop, with the stack fading under it on film. That line is then
          // said in the other language, as the epilogue's were, and shown
          // in this one with the original under it — when there was a menu
          // to switch any of it on.
          let from = j * slice;
          let source = null;
          if (index === SCENES.length - 1 && j === scene.lines.length - 1) {
            from = await epilogue(from, (j + 1) * slice);
            if (menu) source = TRANSLATE.lastSource;
          }
          await say(scene.lines[j], from, (j + 1) * slice, source, wears);
        }

        index = (index + 1) % SCENES.length;
        // The recording is one turn of the loop, cut at the wrap, and the
        // stack it raises should be that turn's: with the epilogue on, the
        // boxes start again from nothing each time round, or the search
        // would light the same line once per turn the page had run.
        if (EPILOGUE && index === 0) past.length = 0;
        // Each turn switches translation on, and both languages with it;
        // the next starts with both off.
        if (index === 0) dropTranslation();
      } catch (error) {
        if (error !== JUMPED) throw error;
        // A jump out of the epilogue leaves nothing raised behind it, no menu
        // open, and translation off again, both languages with it.
        if (EPILOGUE) endEpilogue();
        closeMenu();
        dropTranslation();
        // Somebody picked a scene. Drop whatever was mid-sentence and let the
        // next turn of the loop get there, which is also what makes a second
        // click during a switch work: it lands here again. A window click has
        // already fronted its window, so the next turn finds nothing to switch
        // and goes straight to the captions. The caption that was up keeps
        // its words while the box fades: the next line's own drawLive
        // replaces them, under a box that is only shown again once it has.
        index = jump.index;
        picked = !jump.direct;
        fading = jump.fade;
        jump = null;
        switcher.classList.remove('is-visible');
        box.classList.remove('is-visible');
        progress(0, 0);
      }
    }
  }

  // ── the scene bar ─────────────────────────────────────────────────────────
  //
  // One segment per scene: how far through the loop is, and a way out of waiting
  // for it. Each one jumps to the top of its scene; the one already playing does
  // nothing, because restarting it would punish a click on the thing you are
  // already watching.

  const sceneButtons = [...document.querySelectorAll('.demo-scenes .scene-button')];
  const sceneFills = sceneButtons.map((b) => b.querySelector('.scene-fill'));
  let sceneIndex = 0;

  const paintScene = (index) => {
    // A window you are holding stops being yours when the demo moves on: the
    // loop reaches the next scene, brings another window forward, and the one
    // under the cursor is now behind it. The scene the drag itself asked for
    // does not count, which is what the app check is for.
    if (windowGrab && SCENES[index].app !== windowGrab.win.dataset.app) {
      endWindowDrag();
    }
    sceneIndex = index;
    sceneButtons.forEach((button, i) =>
      button.setAttribute('aria-current', i === index ? 'true' : 'false')
    );
  };

  // The loop hands the bar a target and a duration per caption, and CSS walks it
  // there, rather than the script animating a number frame by frame.
  const progress = (value, ms) => {
    sceneFills.forEach((fill, i) => {
      const to = i < sceneIndex ? 1 : i === sceneIndex ? value : 0;
      fill.style.transitionDuration = (i === sceneIndex ? ms : 0) + 'ms';
      fill.style.transform = 'scaleX(' + to + ')';
    });
  };

  // `direct` skips the ⌘-tab: clicking a window is reaching for that window.
  const jumpTo = (index, direct) => {
    if (index === sceneIndex || !SCENES[index]) return;
    jump = { index: index, direct: !!direct, fade: box.classList.contains('is-visible') };
    paintScene(index);
    box.classList.remove('is-visible');
    progress(0, 0);
    if (direct) {
      front(SCENES[index].app);
      switcher.classList.remove('is-visible');
    }
    // Waking the loop is what makes this instant: it is otherwise sitting in
    // whatever wait it started before the click.
    wake();
  };

  sceneButtons.forEach((button, index) =>
    button.addEventListener('click', () => jumpTo(index, false))
  );

  const sceneOf = (app) => SCENES.findIndex((scene) => scene.app === app);
  windows.forEach((win) =>
    win.addEventListener('click', () => jumpTo(sceneOf(win.dataset.app), true))
  );

  // ── moving the windows ────────────────────────────────────────────────────
  //
  // By the title bar, as on a real desktop, and no modifier: the window comes
  // forward as you take hold of it. Sideways and downwards it can go where it
  // likes and be clipped by the screen; upwards it stops at the top of the
  // stage, which is the underside of the menu bar. Mouse only — on a phone the
  // title bar is inside a page you are trying to scroll.
  //
  // A dragged window is placed in fractions of the screen rather than by the
  // insets it started with, so it keeps its size and its spot at any width.

  const stage = document.querySelector('.demo-stage');
  let windowGrab = null;

  const endWindowDrag = () => {
    if (!windowGrab) return;
    const { handle, pointerId, win } = windowGrab;
    if (handle.hasPointerCapture(pointerId)) handle.releasePointerCapture(pointerId);
    win.classList.remove('is-held');
    windowGrab = null;
  };

  // Every title bar in the window is a handle: a sidebar drawn the Tahoe way
  // carries its own, with the traffic lights, beside the main column's.
  if (stage) windows.forEach((win) => win.querySelectorAll('.win-titlebar').forEach((handle) => {
    handle.addEventListener('pointerdown', (event) => {
      if (event.pointerType !== 'mouse') return;
      event.preventDefault();
      try { handle.setPointerCapture(event.pointerId); } catch (e) { /* pointer gone */ }

      const bounds = stage.getBoundingClientRect();
      const box2 = windowResize.pin(stage, win);
      windowGrab = {
        win: win,
        handle: handle,
        pointerId: event.pointerId,
        x: (event.clientX - bounds.left) / bounds.width - box2.left,
        y: (event.clientY - bounds.top) / bounds.height - box2.top,
      };
      win.classList.add('is-held');
      // Taking hold of a window raises it, which here means playing its scene.
      jumpTo(sceneOf(win.dataset.app), true);
    });

    handle.addEventListener('pointermove', (event) => {
      if (!windowGrab || windowGrab.win !== win) return;
      const bounds = stage.getBoundingClientRect();
      const left = (event.clientX - bounds.left) / bounds.width - windowGrab.x;
      const top = (event.clientY - bounds.top) / bounds.height - windowGrab.y;
      win.style.left = (left * 100) + '%';
      win.style.top = (Math.max(0, top) * 100) + '%';
    });

    ['pointerup', 'pointercancel', 'lostpointercapture'].forEach((type) =>
      handle.addEventListener(type, endWindowDrag)
    );
  }));

  // ── resizing the windows ──────────────────────────────────────────────────
  // By any edge or corner, see windowResize. Front to back is the stack's
  // order read backwards, and taking hold raises, as moving does.
  if (stage) {
    const byApp = (app) => [...windows].find((w) => w.dataset.app === app);
    windowResize.attach({
      stage: stage,
      front: () => [...stack].reverse().map(byApp).filter(Boolean),
      onGrab: (win) => jumpTo(sceneOf(win.dataset.app), true),
    });
  }

  // ── moving the caption box ────────────────────────────────────────────────
  //
  // The app lets the overlay through clicks until you hold shift, at which point
  // it becomes something you can pick up and put somewhere else. This does the
  // same, inside the fake screen, and it cannot be dropped outside it: the box
  // is the thing being demonstrated.

  let boxGrab = null;

  const insideStage = (x, y) => {
    if (!stage) return { x: x, y: y };
    const bounds = stage.getBoundingClientRect();
    const rect = box.getBoundingClientRect();
    const halfWide = rect.width / 2 / bounds.width;
    const halfTall = rect.height / 2 / bounds.height;
    return {
      x: Math.min(Math.max(x, halfWide), 1 - halfWide),
      y: Math.min(Math.max(y, halfTall), 1 - halfTall),
    };
  };

  const placeBox = (at) => {
    box.style.bottom = 'auto';
    box.style.left = (at.x * 100) + '%';
    box.style.top = (at.y * 100) + '%';
    box.style.transform = 'translate(-50%, -50%)';
  };

  // Tabbing away with the key down would otherwise leave it armed forever.
  // ⇧ also takes the stack down while it is held, as the landing pages and
  // the app do: the box is being picked up, and the stack is pinned to it.
  const armBox = (on) => {
    shiftKey = on;
    box.classList.toggle('is-movable', on);
    showHistory();
  };
  window.addEventListener('keydown', (e) => { if (e.key === 'Shift' && !e.repeat) armBox(true); });
  window.addEventListener('keyup', (e) => { if (e.key === 'Shift') armBox(false); });
  window.addEventListener('blur', () => armBox(false));

  box.addEventListener('pointerdown', (event) => {
    if (event.pointerType !== 'mouse' || !event.shiftKey || !stage) return;
    event.preventDefault();
    try { box.setPointerCapture(event.pointerId); } catch (e) { /* pointer gone */ }

    const bounds = stage.getBoundingClientRect();
    const rect = box.getBoundingClientRect();
    const centre = {
      x: (rect.left + rect.width / 2 - bounds.left) / bounds.width,
      y: (rect.top + rect.height / 2 - bounds.top) / bounds.height,
    };
    boxGrab = {
      pointerId: event.pointerId,
      x: centre.x - (event.clientX - bounds.left) / bounds.width,
      y: centre.y - (event.clientY - bounds.top) / bounds.height,
    };
    box.classList.add('is-dragging');
    placeBox(insideStage(centre.x, centre.y));
  });

  box.addEventListener('pointermove', (event) => {
    if (!boxGrab || !stage) return;
    const bounds = stage.getBoundingClientRect();
    placeBox(insideStage(
      (event.clientX - bounds.left) / bounds.width + boxGrab.x,
      (event.clientY - bounds.top) / bounds.height + boxGrab.y
    ));
  });

  ['pointerup', 'pointercancel', 'lostpointercapture'].forEach((type) =>
    box.addEventListener(type, () => {
      boxGrab = null;
      box.classList.remove('is-dragging');
    })
  );

  // ── the pointer reveal and the ⌥ stack ────────────────────────────────────
  //
  // Neither of these is drawn. The page has a pointer and something underneath
  // the captions, which is everything the reveal needs, and a keyboard with the
  // same modifier on it, so both are wired to the real thing and behave as they
  // do in the app. The geometry is in styles.css, against the app's own
  // constants; what is here is where the hole is and what is in the stack.

  const history = document.getElementById('caption-history');

  // The search pill at the stack's edge, as on the landing pages: pinned, the
  // stack stays up with ⌥ released; each keystroke repaints it narrowed and
  // parked on the newest match; unpinned, it answers to ⌥ again, and if it
  // stays up the boxes the search had hidden come back.
  const search = history && stackSearch.attach({
    history: history,
    onPin: () => showHistory(),
    onQuery: () => paintHistory(true),
    onUnpin: (hadQuery) => {
      showHistory();
      // Up still: every box back. Going: the field closes back down to its
      // pill as the stack fades, the boxes left as the search had them.
      if (!history.classList.contains('is-visible')) search.layout(history.offsetWidth, true);
      else if (hadQuery) paintHistory(true);
    },
  });
  const follow = history && stackSearch.follow(history, search);
  let altKey = false;
  let shiftKey = false;
  // The menu's Recent Boxes On ⌥.
  let historyOn = S.historyEnabled;

  // Closed pages, oldest first, at what was the app's `defaultHistoryDepth`
  // until 1.4.0, where the default became every box. The demo keeps the cap:
  // it speaks seven lines on a loop, and a stack of every repetition since the
  // page was opened would be hundreds of the same sentence.
  //
  // Held back to six at first, on the reasoning that this stage is only a few
  // hundred pixels tall and would clip most of them. That was the wrong way
  // round: a stack that always fits is a stack the scroll never does anything
  // to, and scrolling back through the older ones is half of what the feature
  // is. Fifteen overflows this stage comfortably, which is the point.
  //
  // The demo speaks seven distinct lines, so a full buffer repeats them. The
  // app would do the same with a speaker who repeats themselves: closePage only
  // refuses a line identical to the one before it.
  //
  // Or the settings' depth, within the app's own historyDepthCap. Read at
  // each close rather than once, since the app can change it, see
  // applySettings.
  const pastMax = () => Math.min(S.historyDepth, 2000);
  const past = [];
  // Whether a box pages at the settings' maxLines, see `say`.
  const paged = () => Number.isFinite(S.maxLines);

  // The app's expiry for the stack, under a seeded historyExpires: forgotten
  // once no word has arrived for historyExpiry seconds, and not while it is
  // up, since someone holding ⌥ is reading it. Off on the site, see
  // DEMO_DEFAULTS: the loop never falls silent, though one parked out of
  // view does, as the app's overlay does over a paused call. Counted from
  // the last word, as the app counts it, at the close as well as at the
  // word: a page that closes once the silence has begun goes with the rest,
  // rather than standing until the next word, which a parked loop never says.
  let lastTextAt = -Infinity;
  let forgetting = 0;
  const forgotten = () => {
    if (history && history.classList.contains('is-visible')) { forgetting = setTimeout(forgotten, 1000); return; }
    if (!past.length) return;
    past.length = 0;
    showHistory();
  };
  const forget = () => {
    clearTimeout(forgetting);
    if (!S.historyExpires) return;
    forgetting = setTimeout(forgotten, Math.max(0, lastTextAt + S.historyExpiry * 1000 - performance.now()));
  };
  const spoke = () => { lastTextAt = performance.now(); forget(); };

  // Pages carry an id rather than being matched on their text. The demo speaks
  // seven lines into fifteen slots, so the same sentence is in the stack more
  // than once, and keying the reconciliation below on text made two different
  // boxes look like one box that had moved. Everything downstream then rebuilt
  // and re-animated the lot.
  let pageId = 0;

  // Deduplicated against the last entry, as the app's own closePage is: a page
  // can close twice in a beat, and two identical boxes read as a stutter rather
  // than as history.
  const closePage = (line, app, source) => {
    const trimmed = line.trim();
    const last = past[past.length - 1];
    if (!trimmed || (last && trimmed === last.text)) return;
    // Each box wears the app its words arrived under, as the app's pager tags
    // it, not the app of whatever is playing when it closes, and carries
    // what was actually said, for ⌃.
    past.push({ id: ++pageId, text: trimmed, source: source ? source.trim() : null, app: app || playing() });
    if (past.length > pastMax()) past.splice(0, past.length - pastMax());
    forget();
    // A stack already up takes the box in. One that is not may be wanted
    // anyway: ⌥ pressed before anything had closed, and still held, which the
    // app's poll answers the moment a first page does.
    if (history && history.classList.contains('is-visible')) paintHistory();
    else showHistory();
  };

  // The live box's top edge, as the stack should hang off it.
  //
  // Between pages the box is invisible but still holds the caption that just
  // ended, at whatever height that sentence needed. Anchoring to that edge put
  // the stack where a two-line box had left it and then dropped it the moment
  // the next caption came up one line short, which reads as the stack lagging a
  // page behind.
  //
  // The box is bottom-anchored and grows upwards, so its bottom edge is the
  // stable one. While it is down, anchor to where a single line would put the
  // top instead, which is where the next caption opens. A sentence that goes on
  // to wrap still lifts the stack when it wraps, exactly as it does in the app.
  const anchorTop = (rect) => {
    if (box.classList.contains('is-visible')) return rect.top;
    const cs = getComputedStyle(box);
    const line = parseFloat(cs.lineHeight) || parseFloat(cs.fontSize) * 1.2334;
    // Less the line spacing the last line gives back, see .ov-text.
    const oneLine = line + parseFloat(cs.paddingTop) + parseFloat(cs.paddingBottom)
      + (parseFloat(getComputedStyle(textOf(box)).marginBottom) || 0);
    return Math.max(rect.top, rect.bottom - oneLine);
  };

  // Vertical space for the stack on one side of the live box. The gap is the
  // app's 6pt and the margin off the edge of the screen its 12pt, both at 30pt
  // of text, so both in em. The bottom edge needs no such care: it does not move
  // when the caption changes length.
  const roomFor = (above, rect, bounds, em) =>
    (above ? anchorTop(rect) - bounds.top : bounds.bottom - rect.bottom) - em * 0.6;

  // Which side of the live box the stack takes. Decided on the press that raises
  // it and held for as long as it is up: re-deciding it as the box resizes would
  // let one sentence wrapping to a second line throw the stack across it
  // mid-read, which is the app's reasoning too.
  let placedAbove = true;

  // Below this there is not enough room to be worth drawing: the app's 40pt.
  const MIN_ROOM = 1.33;

  // How tall the stack's content is, measured from layout rather than read off
  // `scrollHeight`.
  //
  // A box mid-entrance carries a transform, and a transformed child widens its
  // scroll container's scrollable overflow. So during the rise `scrollHeight`
  // reports a stack up to 0.4em taller than the one that will be standing there
  // a fifth of a second later. Parking the scroll against that number scrolled
  // the content up by those few pixels, and when the transforms resolved the
  // overflow shrank back and the browser clamped the scroll down again: the
  // boxes appeared slightly high and then dropped onto their real position.
  // Nothing engine-specific about it, which is why it happened everywhere.
  //
  // `offsetHeight` is layout and ignores transforms, so this is the height the
  // stack will settle at, available before it gets there.
  const contentHeight = () => {
    const kids = [...history.children];
    if (!kids.length) return 0;
    const gap = parseFloat(getComputedStyle(history).rowGap) || 0;
    return kids.reduce((sum, el) => sum + el.offsetHeight, 0) + gap * (kids.length - 1);
  };

  // How many boxes are still playing their entrance. While any of them is, the
  // scroll geometry below is not to be trusted or written to: a box mid-rise is
  // displaced by its own transform, and that displacement widens the scrollable
  // overflow it is measured against.
  let rising = 0;

  // The exact scroll range, from the browser rather than from arithmetic.
  //
  // This used to sum the children's `offsetHeight`, chosen because offsetHeight
  // is layout and ignores transforms. What it also is, is rounded to whole
  // pixels: the pills are fractional tall, so the error compounded down the
  // stack and a full one was off by several pixels. Parking against that number
  // put the scroll past the real end, the browser clamped it back, and the stack
  // snapped — which is why it only appeared once the history filled up.
  //
  // scrollHeight is exact and fractional. It is only wrong while a transform is
  // in flight, and `rising` is what keeps this from being read then.
  // The stack's padding, a pixel past the boxes at either end (see
  // .demo-history), which its height has to carry on top of the room.
  const slack = () => {
    const cs = getComputedStyle(history);
    return (parseFloat(cs.paddingTop) || 0) + (parseFloat(cs.paddingBottom) || 0);
  };
  const maxScroll = () => Math.max(0, history.scrollHeight - history.clientHeight);

  // Distance between the edge nearest the live box and the end of the content
  // on that side. Zero means the newest box is flush against the live one,
  // which is where the stack parks itself. Everything is measured from that
  // edge because it is the one the reader is anchored to and the end new boxes
  // arrive at — and which edge that is depends on the side the stack took.
  const nearDistance = () =>
    placedAbove ? maxScroll() - history.scrollTop : history.scrollTop;

  // When the reader last turned the wheel, and when we last moved the scroll
  // ourselves. The second exists only to keep the first honest: every write
  // below fires a scroll event, and without telling them apart the stack would
  // read its own corrections as a gesture.
  let userScrolledAt = -1e9;
  let selfScrolledAt = -1e9;

  // Whether the stack is sitting against the live box, tracked rather than
  // measured. Deriving it from the scroll offset meant reading geometry at the
  // one moment it cannot be trusted: a box closing while an earlier one is still
  // rising would have read as the reader having scrolled away, and the stack
  // would have refused to follow the newest box.
  let parked = true;

  const setNearDistance = (distance) => {
    const max = maxScroll();
    const clamped = Math.min(Math.max(distance, 0), max);
    selfScrolledAt = performance.now();
    history.scrollTop = placedAbove ? max - clamped : clamped;
  };

  // Fade each edge that still has boxes beyond it, and only those.
  //
  // The far edge carries the tall fade. The near edge gets a much shorter one,
  // and only once the reader has scrolled away from the live box: parked, the
  // box against the live one is the newest and the one being read, so dimming
  // it would be backwards; scrolled, that edge hides newer boxes, and the short
  // band says so without swallowing what is being read.
  //
  // And only while something is genuinely hidden there. Scroll to the end and
  // the fade goes with it, because a fade with nothing behind it advertises
  // content that is not there. Each band is sized to the amount actually hidden,
  // so a stack overflowing by ten pixels gets a ten-pixel fade rather than
  // swallowing a whole box to announce it, and neither takes more than half
  // the visible height, so the two can meet but never cross.
  const FADE_MAX = 2.2;
  // The app's 60pt against its 150pt far fade.
  const NEAR_FADE_MAX = FADE_MAX * 0.4;

  // Only the depth moves. `is-clipped` is deliberately left alone here and set
  // from layout in placeHistory instead: it carries the mask, and adding or
  // removing a mask on a scroll container disturbs the scroll, so toggling it
  // on every scroll frame put the fade in a fight with the gesture it was
  // reading. A depth of zero looks exactly like no mask and costs the scroller
  // nothing.
  const updateFade = () => {
    if (!history) return;
    const em = parseFloat(getComputedStyle(history).fontSize) || 16;
    const near = Math.max(0, nearDistance());
    const hidden = Math.max(0, maxScroll() - near);
    const fade = Math.min(em * FADE_MAX, hidden, history.clientHeight / 2);
    // Parked, the near band is zero whatever the geometry says. A box rising in
    // at the near end is translated for the length of its entrance, and a
    // transformed box widens the scrollable overflow it sits in, so for those
    // frames the near distance reads as the displacement and the band flashed
    // on and snapped off with the animation. The far band is unaffected: that
    // growth lands at both ends of its measurement and cancels.
    const nearFade = parked ? 0 : Math.min(em * NEAR_FADE_MAX, near, history.clientHeight / 2);
    history.style.setProperty('--fade', fade.toFixed(1) + 'px');
    history.style.setProperty('--near-fade', nearFade.toFixed(1) + 'px');
    placeFade(history);
  };

  // Follows the wheel, not just the moment the stack is built: scrolling is
  // exactly when the amount hidden at each edge changes. One update a frame,
  // because this writes a property and then measures, and doing that on every
  // scroll event is how a handler starts costing more than the scroll.
  let fadeQueued = false;
  if (history) history.addEventListener('scroll', () => {
    if (performance.now() - selfScrolledAt > 60) {
      userScrolledAt = performance.now();
      // Only worth reading between entrances, when the geometry is honest.
      if (!rising) parked = nearDistance() < 1;
    }
    if (fadeQueued) return;
    fadeQueued = true;
    requestAnimationFrame(() => { fadeQueued = false; updateFade(); });
  });

  // Pinned to the live box, so dragging the captions takes the stack with them.
  //
  // Deliberately does not park the scroll. This runs on every frame the stack
  // is up, to follow a live box that moves and resizes under it, and parking
  // here is what threw the reader back to the newest box the instant they
  // scrolled away from it.
  const placeHistory = () => {
    if (!history || !stage) return;
    const bounds = stage.getBoundingClientRect();
    const rect = box.getBoundingClientRect();
    const em = parseFloat(getComputedStyle(history).fontSize) || 16;
    const room = roomFor(placedAbove, rect, bounds, em);
    const near = nearDistance();
    const was = history.clientHeight;
    // The search pill sits at the near edge, a gap off the live box, and the
    // boxes beyond it, so it comes off the room before they are measured
    // against it, as the app's does.
    const block = search.height() + em * 0.2;
    const content = contentHeight();

    // Rounded, because `room` is derived from the live box's rect and jitters by
    // fractions of a pixel as a caption is typed. Left as a float it crossed the
    // half-pixel test below on its own every few frames, and every crossing was
    // a scroll correction the reader had not asked for.
    history.style.maxHeight = (Math.max(0, Math.round(room - block)) + slack()) + 'px';

    // Nowhere left to put it. Hidden rather than emptied, because the live box
    // shrinks again on the next page and the stack should still be there. A
    // stack with nothing in it, every box filtered out, still shows the field,
    // and needs only the field's own height.
    const starved = room < (content > 0 ? em * MIN_ROOM + block : search.height());
    history.classList.toggle('is-starved', starved);
    search.setStarved(starved);
    // Sprung after the live box while the stack is up, straight there when it
    // is arriving, as the app's is.
    const edge = placedAbove ? bounds.bottom - anchorTop(rect) : rect.bottom - bounds.top;
    follow(rect.left + rect.width / 2 - bounds.left, edge + em * 0.2, placedAbove, block,
           history.classList.contains('is-visible') && !starved);
    // Whether the stack can scroll at all, which changes only when a box lands
    // or the live box takes room away — never mid-gesture.
    history.classList.toggle('is-clipped', content > room - block + 1);
    search.layout(history.offsetWidth, history.classList.contains('is-visible'));

    // Only a change of height disturbs the scroller; the live box merely moving
    // does not. Put the reader back the same distance from the live box, so a
    // box growing to a second line eats the stack from the far end rather than
    // sliding it under them.
    // Never mid-gesture. Someone flicking through the stack while a caption
    // happens to resize the live box underneath is navigating, and moving the
    // content under them is the one thing that must not happen — the app draws
    // the same line with `!scroll.isScrolling`.
    if (Math.abs(history.clientHeight - was) > 0.5
        && performance.now() - userScrolledAt > 400
        && !rising) setNearDistance(near);

    updateFade();
  };

  // Reconciled rather than rebuilt, so that a box already on screen is not
  // animated again when a page closes while ⌥ is still held — only the one that
  // just closed rises. The app does the same, against the same problem.
  // `park` forces the scroll to the newest box: the search asks for that on
  // every keystroke, where a page closing leaves the reader where they were.
  const paintHistory = (park) => {
    if (!history) return;
    const fresh = !history.classList.contains('is-visible');
    // Read the reader's place before the rebuild destroys it. Sticking to the
    // newest box is right only if that is where they already were; if they had
    // scrolled back to an older one, hold *that* box still instead. New text
    // arriving must not drag the page out from under someone mid-sentence.
    const wasParked = fresh || !history.children.length || parked;
    const wasNear = nearDistance();
    const wasContent = contentHeight();

    // Reversed when the stack hangs below, so the newest box is the one touching
    // the live box either way.
    const ordered = placedAbove ? past : [...past].reverse();

    // Patched in place. The boxes already standing are never detached, only the
    // ones that have fallen out of the buffer are removed and the new one is
    // inserted where it belongs.
    //
    // The previous version emptied the container and re-appended the survivors,
    // which is what re-ran the entrance on the whole stack: taking an element
    // out of the document and putting it back restarts a CSS animation that is
    // still named on it. Leaving them alone also leaves the scroll position
    // alone, which the browser maintains for as long as the boxes it is
    // measured against stay put.
    const living = new Set(ordered.map((page) => String(page.id)));
    [...history.children].forEach((el) => {
      if (!living.has(el.dataset.pid)) el.remove();
    });

    const risen = [];
    ordered.forEach((page, i) => {
      const here = history.children[i];
      if (here && here.dataset.pid === String(page.id)) return;
      const el = newBox(page.app);
      el.dataset.pid = page.id;
      history.insertBefore(el, here || null);
      risen.push(el);
    });

    // Every box counts towards the width, filtered out or not: a stack that
    // narrowed as the query did would jitter under each keystroke, and the
    // search pill takes its width from the stack's. So the width is read with
    // every box standing, then held while the search hides some. Hidden rather
    // than removed: a box keeps its place for when the query changes.
    const kids = [...history.children];
    const pageOf = (el) => past.find((p) => String(p.id) === el.dataset.pid);
    history.style.minWidth = '';
    kids.forEach((el) => {
      const page = pageOf(el);
      if (page) {
        search.write(textOf(el), lineText(page));
        setUnder(el, underText(page));
      }
      el.classList.remove('is-hidden');
      // The name tab places each box by a margin from the stack's edge
      // (nameTab.settle), and a margin counts towards the width read here:
      // measured with them on, the stack could only ever grow. Off for the
      // reading, and put back when the stack is laid out below.
      el.style.marginInlineStart = '';
    });
    history.style.minWidth = history.offsetWidth + 'px';
    kids.forEach((el) => {
      const page = pageOf(el);
      if (page) el.classList.toggle('is-hidden', !pageMatches(page));
    });

    placeHistory();

    // Settle the scroll while the new boxes are still sitting at their resting
    // position, before a single transform exists to widen the overflow they are
    // measured against. Parked stays parked; otherwise the box they were reading
    // holds still, which means moving with the growth that landed at the near
    // end.
    setNearDistance(park || wasParked ? 0 : wasNear + (contentHeight() - wasContent));
    parked = park || wasParked;

    // Only now do they animate. Nearest the live box first, so the stack unrolls
    // out of it: the newest box is last above the live one and first below. The
    // pill goes before them all when the stack is opening. A box the search
    // hides does not rise: it has nowhere to be seen, and an entrance that never
    // ends would hold the scroll geometry hostage.
    if (fresh) search.rise();
    risen.forEach((el) => {
      if (el.classList.contains('is-hidden')) return;
      const i = kids.indexOf(el);
      el.style.setProperty('--rise', (placedAbove ? kids.length - 1 - i : i) + (fresh ? 1 : 0));
      rising++;
      el.addEventListener('animationend', () => {
        rising = Math.max(0, rising - 1);
        relayer(el);
        // The last entrance over, the geometry is honest again: a wheel turned
        // during the rise went unread, so read it now, and draw the near band
        // it may have earned.
        if (!rising) { parked = nearDistance() < 1; updateFade(); }
      }, { once: true });
      el.classList.add('is-rising');
    });
  };

  // Up while ⌥ is held, never alongside ⇧, which is the app's rule too, or
  // while the search has it pinned, when it stays up whatever the modifier
  // keys are doing.
  const showHistory = () => {
    if (!history || !stage) return;
    const want = historyOn && ((altKey && !shiftKey) || search.pinned) && past.length > 0;

    if (want) {
      // A fresh press builds the stack from nothing, so every box rises. Only
      // while ⌥ is still held does the reconciliation in paintHistory matter,
      // and then it is a single box that just closed, joining a stack that is
      // already up. The app draws the same line.
      if (!history.classList.contains('is-visible')) {
        history.textContent = '';
        // Whatever was still animating went with them, and a fresh press always
        // opens against the live box.
        rising = 0;
        parked = true;

        // Flip only when there is genuinely more room the other way, which is
        // what makes the stack fall below the box once the box is dragged to
        // the top. Decided once, on the press that raises it, and held for as
        // long as it is up: re-deciding it as the box resizes would let one
        // sentence wrapping to a second line throw the stack across it
        // mid-read, which is the app's reasoning too.
        const bounds = stage.getBoundingClientRect();
        const rect = box.getBoundingClientRect();
        const em = parseFloat(getComputedStyle(history).fontSize) || 16;
        placedAbove = roomFor(true, rect, bounds, em) >= roomFor(false, rect, bounds, em);
        history.classList.toggle('is-below', !placedAbove);
        search.setBelow(!placedAbove);
      }
      paintHistory();
    }
    // The boxes are left in place on the way out so the stack fades rather than
    // vanishing; the next press is what clears them.
    history.classList.toggle('is-visible', want);
    search.setVisible(want);
    box.classList.toggle('is-solid', want);
    queueHole();
  };

  // The hole under the pointer, see pointerReveal, and the stack placed again
  // with every paint: it is pinned to the box.
  const hole = pointerReveal(box, screen, {
    on: S.revealEnabled,
    solid: () => box.classList.contains('is-movable') || box.classList.contains('is-solid'),
    onFrame: () => { if (history && history.classList.contains('is-visible')) placeHistory(); },
  });
  const queueHole = hole.queue;

  // Tabbing away with either key down would otherwise leave it armed forever,
  // the same reason armBox watches blur.
  window.addEventListener('keydown', (e) => {
    // Held keys repeat, and a repeat that repainted would restart the stagger
    // over and over for as long as ⌥ is down.
    if (e.key === 'Alt' && !e.repeat) { altKey = true; showHistory(); }
    if (e.key === 'Shift') queueHole();
  });
  window.addEventListener('keyup', (e) => {
    if (e.key === 'Alt') { altKey = false; showHistory(); }
    if (e.key === 'Shift') queueHole();
  });
  window.addEventListener('blur', () => { altKey = false; showHistory(); });

  // Only run while the demo is actually on screen...
  new IntersectionObserver(
    ([entry]) => { onScreen = entry.isIntersecting; sync(); },
    { threshold: 0.15 }
  ).observe(box);

  // ...and only while the tab is in front: timers in a backgrounded tab are
  // throttled to about one a second, which would wreck the pacing.
  document.addEventListener('visibilitychange', sync);

  // A beat after the page is up before anything is said: the screen is
  // seen empty first, and the first caption arrives as every one after it
  // does, rather than being there when the page opens.
  setTimeout(loop, START_MS);
})();
